quests[26780] = { id = 26780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nighttime in the Jungle", description = "Nighttime in Stranglethorn is a beautiful thing.  The skies fill with stars, and the moon casts its rays right between those leaves, right there.  I could stare at these skies all night.\n\nUnfortunately, the trolls that walk the ruins of Zul'Mamwe are interfering with my astronomy.  They burn braziers, day and night, which rob me of the darkness I need.\n\nPlease, {name}... travel east into Zul'Mamwe and put them out.", sourceObjective = "Put out 8 Zul'Mamwe Braziers at Zul'Mamwe in Northern Stranglethorn.", completion = "I can see the difference already.  I can't wait until later tonight, when I get to perform my observations again!", sourceObjectiveStatus = "unverified-source-field" }
quests[26781] = { id = 26781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mind's Eye", description = "One of the Vale's many treasures lies nearby, on OUR side of the giant whirlpool.  The Mind's Eye is held by an ogre mage, in the Mosh'Ogg ogre mound just to the northeast.  His name is Mai'Zoth.  From what I understand, he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nThus far I've been unable to get near enough to take it from him.  Will you give it a try?", sourceObjective = "Obtain the Mind's Eye from Mai'Zoth.", progress = "Do you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, {name}!\n\nAnd to think my brother and sister said we wouldn't find anything of worth here in the Vale.  Hah!  And I'm just getting started!", sourceObjectiveStatus = "unverified-source-field" }
quests[26782] = { id = 26782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that some {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", sourceObjective = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Wulfred peers into the box.>\n\nThis... this is not like what I expected.  I had thought it would be a... a...\n\n<His eyes glaze over.>\n\nAhem!  I'm sorry.  I'm not sure what came over me.  I'll be sending this south, to the Explorers' League Digsite in the Cape.  Maybe they'll know what to do with it...", sourceObjectiveStatus = "unverified-source-field" }
quests[26783] = { id = 26783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that a {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", sourceObjective = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Wulfred peers into the box.>\n\nThis... this is not like what I expected.  I had thought it would be a... a...\n\n<His eyes glaze over.>\n\nAhem!  I'm sorry.  I'm not sure what came over me.  I'll be sending this south, to the Explorers' League Digsite in the Cape.  Maybe they'll know what to do with it...", sourceObjectiveStatus = "unverified-source-field" }
quests[26784] = { id = 26784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muddied Waters", description = "The elemental powers are strong here in the Highlands, {name}. It is why the Twilight's Hammer chose to build their stronghold here.\n\nIn the right hands, we can channel this energy into something productive... like a portal directly to Orgrimmar.\n\nNorthwest of here, at the Verrall River Delta, water elementals have been stirred up by the actions of our foes upstream. Destroy them and gather 5 whirlpool cores. You'll not only calm the river, you'll power up our portal.", sourceObjective = "Slay Muddied Water Elementals to collect 5 Whirlpool Cores.", progress = "I hope the fighting within the river wasn't too dangerous.", completion = "These are perfect! The restless waters of that troubled river will now do much more than move silt or stone... They'll move you across continents.\n\nFinish up the rest of your business here in Dragonmaw and then we should be able to proceed.", sourceObjectiveStatus = "unverified-source-field" }
quests[26785] = { id = 26785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Part of the Pack", description = "I've been trying to keep my true self hidden away from the people of Darkshire... they seem to react poorly to worgen. There are more of us here, though, beyond the city.\n\nThe companions I first traveled here with search the woods for wild worgen. They believe some of them, ones with telltale signs, can still be returned to sanity.\n\nI'm not quite ready to rejoin them. Please send word to Apprentice Fess at the crossroads west of town that I'll be staying in Darkshire a while longer.", sourceObjective = "Speak to Apprentice Fess at the crossroads west of Darkshire in Duskwood.", completion = "Tobias is staying in town still?\n\nMaster Harris warned him not to pursue his brother's fate. We all lead new lives now, after all. But the past is hard to let go of...", sourceObjectiveStatus = "unverified-source-field" }
quests[26786] = { id = 26786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Beach Head", description = "Something troubles me, {name}. The Twilight dragons knew just where and when to strike our airfleet. It's as if they knew our plans.\n\nTwilight spies cower within our midst!\n\nI'm going to take one of our remaining ships back to Orgrimmar to roll some heads. I need you to stay behind and secure this front. The Dragonmaw shaman are powerful; I have asked them to open up a portal to Orgrimmar, and I need you to help.\n\nSo. Start helping!", sourceObjective = "Speak with Artesh at Dragonmaw Port in Twilight Highlands.", completion = "Your Warchief is decisive, {name}. He makes things happen. I like him.\n\nLet's talk about this portal that he wants!", sourceObjectiveStatus = "unverified-source-field" }
quests[26787] = { id = 26787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bear In Mind", description = "I'm afraid that... well, I'm just plain afraid, but I'm also sorry to have to ask for another favor.\n\nMaster Harris needs brains. Bear brains. They're part of the serum apparently, or at least a proper substitute.\n\nThere's plenty of black bears in the woods to the west, and along the riverbank, but... I can't do it! I'm too terrified to go out there and face those huge things, even with a rifle. Please, let me pay you to bring back some!", sourceObjective = "Collect 8 Black Bear Brains.", progress = "Did you get them? Did you?", completion = "Thank you! Oh, thank you. I never thought I'd be happy to smell those brains, but I am now that I didn't have to get them!\n\nHere's your reward as promised...", sourceObjectiveStatus = "unverified-source-field" }
quests[26788] = { id = 26788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cementing Our Victory", description = "Our alliance with the Dragonmaw is secured, but this port is far from combat ready. These flimsy wooden walls are an embarrassment to the Warchief.\n\nWhen water elementals carve their way through rock, as they have in the Verrall River, they create a peculiar kind of muck. It spreads easily and dries harder than the hardest stone. It's the perfect mortar for large-scale construction.\n\nGo to the river delta northwest of here and collect some Verrall River muck. Even a little will go a long way.", sourceObjective = "Collect 10 piles of Verrall River Muck.", progress = "Do you have the mud? Construction of the new walls has already begun!", completion = "<Ornak allows the muck to drip from his fingertips.>\n\nNow that's the stuff! I'll start mixing and diluting this with gravel and water. Just a few handfuls of this can enhance enough cement for an entire stone tower.\n\nWe've got big plans for this port, {name}. You'll see!", sourceObjectiveStatus = "unverified-source-field" }
quests[26789] = { id = 26789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You no take axe!", description = "{name}, we have a problem! I've tracked down the demon-hound Magmadar to this clearing, but when we resting a band of kobolds took our battle axes! I need you to retrieve them, lest Magmadar catch us off guard! Hurry, he could awaken at any moment!", sourceObjective = "Kill 5 Test Kobolds.", sourceObjectiveStatus = "unverified-source-field" }
quests[26791] = { id = 26791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprout No More", description = "The stone trogg mystics are creating those fungal monstrosities from the giant mushrooms to the north.\n\nI want you to take a war guardian to help deal with the giants and stone troggs. Make your way to the giant mushrooms and target them. I and my geomancers will sink them into the ground before the mystics have a chance to finish their ritual.", sourceObjective = "Interact with and gain a War Guardian, and destroy 5 Giant Mushrooms.", progress = "Don't forget to use the war guardian to help you. The chasm is teeming with mystics and fungal monstrosities.", completion = "They won't have any more of those fungal giants to throw against us!", sourceObjectiveStatus = "unverified-source-field" }
quests[26792] = { id = 26792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Monstrosities", description = "Grab yourself a war guardian, and destroy those fungal monstrosities while you're out there.", sourceObjective = "Slay 5 Fungal Monstrosities.", completion = "Thank you, {name}. We've never had such a problem in Deepholm before the destruction of the World Pillar.\n\nYour Earthen Ring must repair the damage before it's too late.", sourceObjectiveStatus = "unverified-source-field" }
quests[26793] = { id = 26793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weathered Grave", description = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>", sourceObjective = "Speak with Sirra Von'Indi in Darkshire.", completion = "Morgan Ladimore?\n\nAhh, yes, of course. His was a long and sorrowful tale. I knew him, well, before he left for the war, but that was the last time I saw him. A noble and good man, he was, but he suffered a bad end.\n\nHere, I should have something here that can tell the tale better than my own recollections...", sourceObjectiveStatus = "unverified-source-field" }
quests[26794] = { id = 26794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Ladimore", description = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.", sourceObjective = "Speak with Commander Althea Ebonlocke in Darkshire.", completion = "Morgan Ladimore? Never heard of...\n\nOh, you mean Mor'Ladim! I guess you haven't heard the story?\n\nWell, I'll give you the short version. A powerful undead calling itself Mor'Ladim has been wandering Duskwood. From what we've gathered, it appears to be the undead body of Morgan Ladimore, of whom you apparently know. He's been causing us all sorts of problems, attacking Watchmen on patrol and killing people.\n\n<She sizes you up.>\n\nYou seem to be capable enough, maybe you could lay him to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26795] = { id = 26795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'Ladim", description = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.", sourceObjective = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.", progress = "I don't blame you if you're having trouble with him, {name}. Some of our strongest Watchers have been lost to Mor'Ladim.", completion = "You killed him? That's no small accomplishment, {name}! On behalf of the people of Darkshire and the Night Watch, I thank you.\n\nAh... there is one small matter, however...", sourceObjectiveStatus = "unverified-source-field" }
quests[26796] = { id = 26796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Daughter Who Lived", description = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", sourceObjective = "Speak with Watcher Sarah Ladimore in Darkshire.", completion = "Yes? My father...\n\n<Her eyes become downcast.>\n\nI wish... there was something I could have done for him... If only I had talked to him before he...", sourceObjectiveStatus = "unverified-source-field" }
quests[26797] = { id = 26797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Daughter's Love", description = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, {name}.", sourceObjective = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.", progress = "Leave me be...", completion = "<A ghostly voice sounds on the wind...>\n\nThis is...? Sarah? Could it be she's still alive? The weight is removed from my shoulders...\n\n{name}. Take my sword, Archeus. As my soul is put to rest, I have no more need for it. It was forged to do good, and though I have proved myself unworthy to hold it, perhaps you will carry on the Light through it.\n\nLys, my love...", sourceObjectiveStatus = "unverified-source-field" }
quests[26798] = { id = 26798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Will be Pleased", description = "The portal is ready!\n\nIt's not powerful enough to transport an army, but we can maintain the connection long enough to allow important individuals to pass back and forth.\n\nThe Warchief will want to know about our progress here. Walk through the portal to Orgrimmar, then deliver the news to Garrosh Hellscream.", sourceObjective = "Use the portal in Dragonmaw Port to go to Orgrimmar and report to Garrosh Hellscream.", completion = "{class}, you've returned from Dragonmaw. The portal is functioning then? Good.\n\nBefore you return to your work there, we've got some dirty business to clean up right here in Orgrimmar...", sourceObjectiveStatus = "unverified-source-field" }
quests[26799] = { id = 26799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those That Couldn't Be Saved", description = "The val'kyr raise hundreds of corpses every day.  Agatha raised you just a few moments ago.  Not all are as lucky as you, however.\n\nSome maintain their free will, but live in constant fear and confusion.  They usually run off into the woods, cowering at their own reflections.\n\nOthers lose their minds completely, shambling about aimlessly.  They often turn to violence, and must be destroyed.\n\nThis is your task, {name}.  Destroy them, our former brothers and sisters though they might be.", sourceObjective = "Kill 6 Mindless Zombies.", completion = "Not even the power of the val'kyr was enough to save these creatures.  They were doomed from the beginning.\n\nI have obtained some equipment for you, {name}.  It's not much, but it will help.  Please, take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[26800] = { id = 26800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruitment", description = "We've been shipping in dead bodies from Silverpine, Hillsbrad... hell, anywhere we can get them from.  We can't, however, afford to ignore the bodies which are sitting right on our front doorstep.\n\nThe last vestiges of the Scarlet Crusade roam here in Tirisfal Glades.  While we've managed to push them from Deathknell, several of their bodies litter the buildings to the north and the east.\n\nGo find them... and bring that Darnell fellow with you.  He looks strong enough to carry a few corpses.", sourceObjective = "Search Deathknell and the vicinity for 6 Scarlet Corpses, then point at them so Darnell can pick them up.", completion = "Great work {name}.  I knew you weren't useless.\n\nHere, take one of these.  We deathguards have piles of these things just sitting around.", sourceObjectiveStatus = "unverified-source-field" }
quests[26801] = { id = 26801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge on our Perimeter", description = "If you're going to be an asset to the Forsaken, you need to learn how to fight.  And there's no better target than the Scourge minions that continue to pester us.\n\nThe wretched ghouls and Rattlecage skeletons that roam the north and to the east are former troopers of the fallen Scourge.  They should prove to be an even match for a fledgling {class} like you.\n\nDo not tarry - when you are done, speak to me again.", sourceObjective = "Kill 8 undead outside of Deathknell. You may kill either Wretched Ghouls or Rattlecage Skeletons.", progress = "Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village.  Let's hope you will fare better than them, yes?", completion = "You're growing in strength, {name}.  I've seen your type before.  You will be moving out of Deathknell and on to greater things before long.  Just make sure you don't lose sight of where you started.\n\nYou have much to accomplish, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26802] = { id = 26802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damned", description = "First of all, look at your armor.  You're a mess, {class}.\n\nIf you'd like to stay in one piece--and I've no doubt you do--perhaps I can help.  If you can gather some paws and wings from the wolves and bats nearby, maybe I'll find some armor for you.  You'll find the creatures to the north and to the west of here.", sourceObjective = "Obtain 4 Scavenger Paws and 4 Duskbat Wings.", progress = "Do try your best to keep yourself unharmed until I get you some armor.", completion = "Thank you, {name}. This armor should help you out.\n\nHopefully, it should do you more good than the last one to wear it...", sourceObjectiveStatus = "unverified-source-field" }
quests[26803] = { id = 26803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Reports", description = "Garrosh is brash and speaks harshly, but his intentions are good. In time, he will grow to see your people as a valuable ally.\n\nI am awaiting reports about recent Alliance activity in Durotar, but they haven't arrived yet. Would you be willing to visit Razor Hill and ask him for the reports in person? The easiest way to get there is by wind rider. Doras, Orgrimmar's wind rider master will let you use one of his wind riders for a small fee. Look for him on the rise north of the Valley of Strength.", sourceObjective = "Talk to Orgrimmar's wind rider master, Doras.", completion = "So you need to get to Razor Hill in a hurry? That's no problem at all. One of my wind riders will get you there very quickly and it only costs a few coins to hire one.", sourceObjectiveStatus = "unverified-source-field" }
quests[26804] = { id = 26804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight to Razor Hill", description = "When you're ready to take the wind rider down to Razor Hill, simply speak with me again. When you get there, waste no time in finding Gar'Thok. He's the one responsible for preparing reports on recent Alliance activity in Durotar.", sourceObjective = "Speak to Doras to purchase a wind rider ride to Razor Hill. Once you arrive, speak with Gar'Thok.", completion = "Eitrigg sent you? The warchief must be getting anxious to read my reports. I'd've sent them long ago, but each day we discover more about the Alliance's plans for invading Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26805] = { id = 26805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Cape!", description = "The Explorers' League is growing, {name}.  Not only have they taken in worgen like me, but they have expanded their range in search of artifacts.  One of our best, Bronwyn Hewstrike, has set up a camp in the south, where he believes an item of titan origin may be hidden.\n\nBronwyn asked me to perform some duties here in the north, one of which was to identify potential recruits.  You seem to be made of the right stuff.  Talk to Robert Rhodes, the flight master, and he'll send you down there.  Bronwyn's treat.", sourceObjective = "Speak with Robert Rhodes to obtain a flight to the Explorers' League Digsite in the Cape of Stranglethorn.", completion = "Wulfred has a good eye.  I think you'll do just fine here at my camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[26806] = { id = 26806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reports to Orgrimmar", description = "Eitrigg will have to be happy with the part of the report that I've finished. Tell him to expect more in the future.\n\n<Gar'Thok hands you a stack of roughly folded papers.>\n\nThis should cover the most important details of the increase in Alliance forces working out of Northwatch. Please apologize to Eitrigg for me and let him know that we've had our hands full here, trying to keep Razor Hill secure and supplied. When you're ready to return to Orgrimmar, simply speak to Burok and hire a wind rider.", sourceObjective = "Take Gar'Thok's Reports to Burok at Razor Hill.", progress = "Are you ready to return to Orgrimmar?", completion = "Ready to return to Orgrimmar with those reports? I can arrange a flight for you right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[26807] = { id = 26807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Eitrigg", description = "Since you've already spoken to Doras, you'll be able to hire a wind rider to take you right back to Orgrimmar. Each time you arrive in a new town, be sure to speak with the town's flight master. After that, you'll be able to use the flight master's services to travel quickly.\n\nSpeak to me again when you're ready to purchase a return flight to Orgrimmar. Bring those reports to Eitrigg in the Valley of Strength once you've landed.", sourceObjective = "Speak with Burok and purchase a flight back to Orgrimmar. Once in Orgrimmar, bring Gar'Thok's Reports to Eitrigg in the Valley of Strength.", progress = "Did you bring those reports?", completion = "<Eitrigg examines the reports.>\n\nThe Alliance has grown bolder than we'd thought! I'll talk to the warchief about sending reinforcements right away. Thank you for getting these reports to me so quickly. I hope this coin is enough to cover your travel expenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[26808] = { id = 26808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maywiki", description = "<Linzi looks troubled.>\n\nYou know, there's a troll hiding behind that pile of boxes.  She must be awfully sad, if she doesn't want to come out and talk to anyone.\n\n<Linzi places some of the Akiris reeds in a kerchief and ties it together.>\n\nHere, give these to her.  They're very soft, and that maybe they will make her feel a little more comfortable back there.", sourceObjective = "Bring Linzi's Gift to Maywiki of Zuldazar at the Explorers' League Digsite.", progress = "Care to explain yourself, {class}?", completion = "<The troll looks into the package.>\n\nYou have my thanks.  You may tell your young dwarven friend that I am not sad.  I am waiting.  For you.\n\nI have identified you as the most promising {race} here in this strange town.  I have a task for you, if you would be willing to take it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26809] = { id = 26809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backdoor Dealings", description = "Zanzil the Outcast, an exile from the Gurubashi tribe, is my quarry.  Recently, I have heard tales from my brothers in the north about his planned reentry into society, starting with the emissary he sent to the Skullsplitters.  This is not good news.\n\nI want you to peer into Zanzil's current plans.  Take this incense, and place it in front of the bat totem in the Ruins of Jubuwal, to the north.  Hir'eek will guide you from there.", sourceObjective = "Place the Gurubashi Incense in front of the Totem of Hir'eek, then listen to Zanzil's plot.", completion = "It is as I suspected.  Zanzil is too haughty to interfere with the squabbles between the Bloodscalps and the Skullsplitters.  No, he is playing a part in a grander scheme... Jin'do the Hexxer is using him to help bring Hakkar back to Zul'Gurub.\n\nIt's good that we found this out now, because it offers us a simple solution.", sourceObjectiveStatus = "unverified-source-field" }
quests[26810] = { id = 26810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Outcast", description = "You are to kill Zanzil.  You rode on Hir'eek's wings and saw through Hir'eek's eyes; you know where Zanzil hides within the Ruins of Aboraz.  Travel there and kill him.\n\nOh, and {race}: if we become separated, you should use this fetish.  It only works within Stranglethorn, but it will transport you back here to me should you need to return switfly.\n\nGood luck, {race}.  Zanzil is no ordinary opponent.", sourceObjective = "Travel to the Ruins of Aboraz in the Cape of Stranglethorn and deal with Zanzil the Outcast.", sourceObjectiveStatus = "unverified-source-field" }
quests[26811] = { id = 26811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Troll Hole", description = "It looks like Zanzil's portal into Zul'Gurub is still open.  Zul'Gurub is a dangerous place, but Maywiki entrusted this task to you.\n\nThe portal lies in wait in front of you.", sourceObjective = "Use Zanzil's Portal and enter Zul'Gurub.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", sourceObjectiveStatus = "unverified-source-field" }
quests[26812] = { id = 26812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priestess Jeklik", description = "Ahead of you looms a ramp up to one of the city's many terraces.  The bat-shaped totems ahead of you indicate that this is the domain of High Priestess Jeklik, a follower of Hir'eek.\n\nJeklik was one of the Hakkar-worshipping priests that Zanzil was planning to resurrect.  Perhaps if you hurry, you can stop the resurrection!", sourceObjective = "Destroy High Priestess Jeklik's body before Zanzil can resurrect her.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", sourceObjectiveStatus = "unverified-source-field" }
quests[26813] = { id = 26813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunging Into Zul'Gurub", description = "Zanzil the Outcast has once again escaped through one of his portals.  Follow him!", sourceObjective = "Pass through Zanzil's Portal.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", sourceObjectiveStatus = "unverified-source-field" }
quests[26814] = { id = 26814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priest Venoxis", description = "Venoxis was the second of the two priests that Zanzil planned to bring back from the dead.  You have already succeeded in destroying the body of High Priestess Jeklik... Venoxis must be the next.", sourceObjective = "Deal with Zanzil the Outcast and High Priest Venoxis.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", progress = "You've been on quite the adventure, I see.", completion = "I ask you to slay Zanzil the Outcast, a lowly, hermetic exile of the Gurubashi, and what do you do?  You dash headfirst into the Gurubashi capital and eliminate one of their High Priests!  Very nearly two!  Only one word suffices to explain such a rash and foolhardy endeavor:\n\nHeroism.\n\nJin'do the Hexxer still walks within Zul'Gurub's walls, but he lost one of his legs when you crushed Jeklik.  Today's battle is ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[26815] = { id = 26815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzil's Secret", description = "Years ago, the Gurubashi exiled one of their own from Zul'Gurub: a troll by the name of Zanzil.  The reasons why aren't all that clear, but I'd guess it had something to do with his tendency to administer powerful, behavior-altering drugs to anyone he saw.  Anyhow, the Gurubashi priests and their blood god have been slain, but Zanzil the Outcast remains...\n\n...as do his powerful, behavior-altering drugs.\n\nI need his mixture for my next test.  Check the zombies to the north.", sourceObjective = "Obtain 5 vials of Zanzil's Mixture.", progress = "Excellent... you're not a zombie yet.  That's good.\n\nOh, umm... nothing.  It's just that... that was a potential risk.  Did I forget to warn you?", completion = "<Dask carefully analyzes the strange compound.>\n\nThis mixture is... PERFECT!  Let's see what it does to your potentially-titan artifact here!", sourceObjectiveStatus = "unverified-source-field" }
quests[26816] = { id = 26816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recipe for Disaster", description = "Did you see that explosion I made?  I must have flown 10 inches off the ground!\n\nI've just got to get Zanzil's recipe so I can find out why it did that.  One of Zanzil's flunkies at the Ruins of Aboraz must have it on him.  Head east, to the coast of the Cape, and snatch it for me!", sourceObjective = "Obtain Zanzil's Formulation from one of Zanzil's followers in the Ruins of Aboraz.", progress = "Did he use shimmerweed?  I'm guessing he used shimmerweed.\n\nNo wait... amberseeds!  It's gotta be amberseeds.", completion = "This is fascinating!  Just think of all the applications!\n\nThanks again, {name}.  Remember, if you ever need anything mixed for you... and I mean ANYTHING... you can always ask The Flask.", sourceObjectiveStatus = "unverified-source-field" }
quests[26817] = { id = 26817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfectly Pure", description = "This humour won't serve on its own.  Too thick.  WAY too thick.\n\nThe nagas to our west maintain a shrine that dispenses the only clean water this side of Duskwood.  For most potions, I'll use river water, but Bronwyn demands accuracy!\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", sourceObjective = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", progress = "<Dask looks eagerly at your pack as you approach.>", completion = "Do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nAlright, let's get this mix started!", sourceObjectiveStatus = "unverified-source-field" }
quests[26818] = { id = 26818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plush Pelts", description = "Hi, I'm the town merchant!  And Bronwyn's my dad!\n\nSorry, I shouldn't get too excited.  Father says it's not professional.\n\nAnyhow, people always come to me asking for heavy leather, or rough hides, but I think they might also like it if I had some soft materials... like tiger fur!  Think you could get some for me?\n\nYou'll find a few panthers nearby, but if you want to see the big tigers, you'll have to go northwest from here... north of that big troll arena.", sourceObjective = "Obtain 4 Supple Tiger Furs and 4 Velvety Panther Furs.", progress = "Oooh... I hope they're soft!", completion = "<Linzi feels the hides and smiles to herself.>\n\nThese are so nice and cushy!  I think my customers are going to LOVE them!", sourceObjectiveStatus = "unverified-source-field" }
quests[26819] = { id = 26819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akiris by the Bundle", description = "The naga explorers to our west carry a valuable ocean reed - Akiris reeds.  Traders use them to make medicines and poultices, and craftsmen use them to line armor or even wrap cigars!\n\nIn the evenings, when digging's done, father's been teaching me how to use them... but unfortunately, we ran out.  Would you mind getting us some more?", sourceObjective = "Obtain 6 Akiris Reeds from Naga Explorers.", progress = "Welcome back!", completion = "Hooray!  It's been days and days since we last had Akiris reeds!", sourceObjectiveStatus = "unverified-source-field" }
quests[26820] = { id = 26820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If They're Just Going to Leave Them Lying Around...", description = "Father says that a responsible merchant is always keeping an eye out for good deals.  I've been trying to look for deals everywhere I go, and I think I've just found one!\n\nThe naga to the west have dozens of statues that they place on the ground where they live.  They couldn't possibly need all of them... so I was thinking that we'd take some for ourselves!\n\nFree statues!  That's a good deal, right?", sourceObjective = "Obtain 6 Naga Icons from the Southern Savage Coast in the Cape of Stranglethorn.", progress = "Let's see 'em!", completion = "These statues are beautiful...\n\nWow, I had no idea the naga were so talented.  Thanks, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26821] = { id = 26821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Airwyn Bantamflax", description = "Well, we have no idea what this artifact is.  It's old, older than dirt... but not titan.  I'm completely dumbstruck.\n\nAirwyn Bantamflax in Booty Bay is my direct superior.  Our next step should be to inform her of this find.  Please, would you bring it to her?", sourceObjective = "Bring the Opened Mosh'ogg Bounty to Airwyn Bantamflax at Booty Bay in the Cape of Stranglethorn.", progress = "Yes, {race}?  I'm quite busy.", completion = "Fascinating!\n\nI'll need some time to study this.  Why don't you have a look around Booty Bay and come back later?", sourceObjectiveStatus = "unverified-source-field" }
quests[26822] = { id = 26822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good-Fer-Nothin' Slither-Dogs", description = "Ahem!  Hrm, hrm...\n\n<The dwarf clears his throat for several seconds.>\n\nYou're lookin' fer somethin' ta do?  And ya come askin' ME?  Lowly ol' Goris?!\n\nWell, ah... this is a first.  Ah, I've got it!\n\nThe vale ta tha north is filled with a bunch o' useless, belly-scrapin' basilisks.  They don't do nothin' for no one, and I hear they turned a guy ta stone once.\n\nIf ya kill 'em, I'll give ya some o' my stuff.", sourceObjective = "Kill 12 Thrashtail or Ironjaw Basilisks.", progress = "This is kinda fun.  Sendin' folks out ta do work for me... better than lousy ol' guard duty.", completion = "Ahem!  Ahhh... right...\n\nWell done!  And, congratulations, on killing them, I mean.\n\nHere you go.", sourceObjectiveStatus = "unverified-source-field" }
quests[26823] = { id = 26823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Big For His Britches", description = "Whatever it is you want to do: I've got a recipe that'll do exactly that.  You want an exploding potion?  BOOM!!  You want a lightning potion?  ZAP!!  You want a shrinking potion?  Smeerp.\n\nSo Bronwyn says he wants a carbon-dating potion?  Easy.  I could make that in my sleep.  The thing is... if we want it to be accurate, I need you to get some quality ingredients.\n\nStart with some humour from a basilisk to the north.  It'll need to be a pretty big basilisk...", sourceObjective = "Obtain a vial of Ironjaw Humour from the Ironjaw Behemoth in the Crystalvein Mine.", progress = "You got the task?  I got the flask.", completion = "Alright!  Step one - getting ingredients - is all done.  Time for the next step: getting more ingredients.", sourceObjectiveStatus = "unverified-source-field" }
quests[26824] = { id = 26824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Results: Inconclusive", description = "I did all I could, {name}.  I had the right potions... I had the right recipes... but the source of this sample eludes me.  It's tens of thousands of years old, but we've shown that it's not of titan origin.  And it's not saronite, I can tell you just by looking at it.  So... what in Brann's name is it?\n\nTell Bronwyn that I tried my best.  Sorry.", sourceObjective = "Return the Opened Mosh'Ogg Bounty to Bronwyn at the Explorers' League Camp in the Cape of Stranglethorn.", progress = "I saw smoke.  Everything alright?", completion = "I knew that alchemist was all talk.  Well, thanks for your help, {name}.  I know you tried.", sourceObjectiveStatus = "unverified-source-field" }
quests[26825] = { id = 26825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"The Flask\" Gobfizzle", description = "Hey - you must be that <fella'/lass> that Wulfred was talkin' about!  The one who found the ogre artifact, and helped him test out those strange stones from up north.  Welcome to the digsite, {name}!\n\nWe were actually working on identifying those samples right as you got here.  Would you mind bringing the sample over to Dask?  I need him to help me find out how old it is.", sourceObjective = "Bring the Opened Mosh'Ogg Bounty to Dask \"The Flask\" Gobfizzle at the Explorers' League Digsite in the Cape of Stranglethorn.", progress = "You got something that needs mixing?", completion = "So once again, it falls upon tiny Dask to get the Explorers' League work done!  Alright... let's see what you've got in there.", sourceObjectiveStatus = "unverified-source-field" }
quests[26826] = { id = 26826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"The Flask\" Gobfizzle", description = "Hey - you must be that <fella'/lass> that Wulfred was talkin' about!  Welcome to the digsite, {name}.\n\nWe were actually just starting a project when you arrived.  Would you mind bringing this sample over to Dask?  I need him to help me find out how old it is.", sourceObjective = "Bring the Opened Mosh'Ogg Bounty to Dask \"The Flask\" Gobfizzle at the Explorers' League Digsite in the Cape of Stranglethorn.", progress = "You got something that needs mixing?", completion = "So once again, it falls upon tiny Dask to get the Explorers' League work done!  Alright... let's see what you've got in there.", sourceObjectiveStatus = "unverified-source-field" }
quests[26827] = { id = 26827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying the Earthen Ring", description = "We must be rallyin' da Earthen Ring for dis fight. What we be lackin' in numbers, we make up for in strength.\n\nGo to tha temple and gather da restin' shaman from tha rear rooms. Norsala, Lorvarius, and I will be meetin' them at Lorthuna's Gate.", sourceObjective = "Rally 5 shaman in the rear of the Temple of Earth, and then speak to Maruut Stonebinder.", completion = "You've done what I thought not possible. Quite impressive, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26828] = { id = 26828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Part of the Bargain", description = "Sadly, I must stay and hold the rift, so you will have to battle without me. Go now to Therazane and join the battle, as promised. You should find her at the Halcyon Egress, north of Lorthuna's Gate and east of the Scoured Reach.\n\nWhen our part of the bargain is fulfilled, bring the last piece of the World Pillar here as quickly as possible.", sourceObjective = "Speak to Therazane on the Halcyon Egress.", completion = "And so you arrive, fleshling.  As promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[26829] = { id = 26829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone March", description = "My forces have already begun the assault. Join them. Spill the blood of these cultists upon the ground, that I might feel how they suffer.", sourceObjective = "Kill 15 Twilight Precipice Cultists.", completion = "Their blood upon the earth is a sweet thing. I shall cherish every moment, slowly extinguishing the stragglers from my realm.", sourceObjectiveStatus = "unverified-source-field" }
quests[26830] = { id = 26830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitor's Bait", description = "I haven't given up my search for the Twilight's Hammer agents that lurk here in Orgrimmar. I need someone I can trust to collect the final evidence of treachery.\n\n<Hellscream pulls you aside.>\n\nSauranok the Mystic - my own most trusted advisor! - is under suspicion. Uncover the truth, {name}, and you'll be rewarded.\n\nI understand Twilight's Hammer has infiltrated workers at the airship docks, to spread their lies all over the continent. Question them. If you discover Sauranok's guilt... Kill him.", sourceObjective = "Question Orgrimmar Skyway Peons around the Zeppelin Towers. Look for any Suspicious Peons. Try to flush out Sauranok the Mystic and kill him.", progress = "Good to see you're still alive, {class}. How goes your investigation?", completion = "Sauranok, Sauranok. His own visions worked against him. Twilight's Hammer probably corrupted him from afar. Bah! Weak! We'll speak his name no more.\n\nI told him you were investigating the airship docks, {name}. To flush him out. Yes, I used you as bait. You served your Horde well, and deserve a reward for outing this viper from our midst.", sourceObjectiveStatus = "unverified-source-field" }
quests[26831] = { id = 26831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Flight", description = "Terrath wants you to make your way to the far end of the precipice to fight Zoltrik Drakebane. He is on his way there as well, but he thinks Zoltrik is likely to take to the sky.\n\nQuite an impression you seem to have made, little one. Have you ever mused that none of this would have happened if I had just stepped on you during our first meeting? Fate is a strange thing.", sourceObjective = "Defeat Zoltrik Drakebane.", progress = "It is good to see you on the battlefield again.", completion = "It is good that you were here. I find my size to be inhibiting when it comes to dragon riding, strangely.", sourceObjectiveStatus = "unverified-source-field" }
quests[26832] = { id = 26832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therazane's Mercy", description = "There are two leaders among the Twilight that need to be killed.\n\nOne is a human by the name of Boldrich. Small, as you are. But still dangerous, as you also are.\n\nThe other is a priestess by the name of Lorthuna. She is wily and hard to corner. Strike swiftly and do not let her escape, or I promise you, you will regret it later.", sourceObjective = "Defeat Boldrich Stonerender and High Priestess Lorthuna.", completion = "You let Lorthuna escape? I warned you of this.\n\nStill, their forces are shattered and their resources cut off. There is little they can do to me or my allies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26833] = { id = 26833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word In Stone", description = "You have done as I've asked of you, {race}. I shall honor my word. Gorsik will meet you at the temple with our piece of the World Pillar.\n\nFinish your ritual and bind the rift. After you have done such, tell your Earthen Ring to leave this place.\n\nYou however... you can stay for a time if you want. You've earned at least that.", sourceObjective = "Speak to Maruut Stonebinder in the Temple of Earth.", completion = "Gorsik has arrived. All of the pieces of the World Pillar are here, thanks to you.\n\nWhat you have done for us is immeasurable.  These final moments shall be the most crucial.  I hesitate to ask more of you, but I'd like you to stay with us and see this through.\n\nThe Twilight's Hammer was devastated by your attacks, but not destroyed.  It's no stretch to assume they will try to stop us from completing our ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[26834] = { id = 26834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down Into the Chasm", description = "Down below in Needlerock Chasm is where the mystics are sprouting all of these fungal monstrosities. I sent Slate Quicksand and a small force to deal with it, but they've run into a snag.\n\nYou remember the Arch Geomancer? Would you fly down there to the northeast and lend him a hand?", sourceObjective = "Speak with Slate Quicksand at Needlerock Chasm in Deepholm.", completion = "Good to see you again, {name}. Now we'll get somewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[26835] = { id = 26835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slight Problem", description = "While you were out there, Pyrium Lodestone contacted me. He said that there is a matter of great urgency and that your assistance is needed immediately. Return to him at the entrance to Needlerock Slag to the southwest.\n\nI wish you luck with the rescue of the Stonefather and the recovery of the middle fragment.", sourceObjective = "Return to Pyrium Lodestone at Needlerock Slag in Deepholm.", completion = "{name}, we have good news and a slight problem....", sourceObjectiveStatus = "unverified-source-field" }
quests[26836] = { id = 26836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Stonefather... and Flint", description = "We found out where the Stonefather is being held and young Flint ran off on his own to rescue him!\n\nI don't have to tell you that this is bad. Flint is going to get himself captured as well, or worse!\n\nThe stone trogg chieftain, Bouldergut, is at the end of the ledges above Needlerock Chasm to the north.\n\nPlease, {name}, you must go after Flint and free the Stonefather before we lose them both!", sourceObjective = "Free Stonefather Oremantle.", progress = "You must rescue Stonefather Oremantle. There's no time to waste, {name}!", completion = "{name}! You did it! How will we ever repay you?", sourceObjectiveStatus = "unverified-source-field" }
quests[26837] = { id = 26837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Explorers' League Digsite", description = "Say, {name}... you seem suitable.\n\nBronwyn Hewstrike of the Explorers' League has been asking for recruits at his digsite in the Cape of Stranglethorn.  Personally, I don't understand why he can't just go down to Booty Bay and find his recruits there... pirates are easily swayed by a couple pieces of gold.\n\nEither way... rumors are he's finally found something in that jungle.  I wonder what it is?", sourceObjective = "Report to Bronwyn Hewstrike at the Explorers' League Digsite in the Cape of Stranglethorn.Say, {name}... you seem suitable.\n\nBronwyn Hewstrike of the Explorers' League has been asking for recruits at his digsite in the Cape of Stranglethorn. Personally, I don't understand why he can't just go down to Booty Bay and find his recruits there... pirates are easily swayed by a couple pieces of gold.\n\nEither way... rumors are he's finally found something in that jungle. I wonder what it is?", sourceObjectiveStatus = "unverified-source-field" }
quests[26838] = { id = 26838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebels Without a Clue", description = "Several years ago, Stormwind's Captain Kurzen brought a brigade into Stranglethorn Vale on a mission whose details are still murky.  Kurzen swiftly descended into madness, as did his men... except for a few rebels who made it their mission to undo the evils that Kurzen had wrought.\n\nAs I said, that was years ago.  I'm now hearing rumors that Kurzen is dead, but those rebels still persist at their rebellion.  If you wish to investigate, you'll find them at a camp on Stranglethorn's northern border.", sourceObjective = "Report to Lieutenant Doren at the Rebel Camp in Northern Stranglethorn.", completion = "Welcome to our camp, {class}.  You couldn't have arrived at a better time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26839] = { id = 26839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Away From It All!", description = "Say, {class}, you look tired.  Carrying around that heavy wallet... er, I mean... heavy equipment... must be a strain on your poor {race} back.\n\nSassy Hardwrench has recently established a premier five-star resort on the sparkling coast off the Cape of Stranglethorn.  Balloon tours, rowboating, day trips to Booty Bay... they've got it all.\n\nYou should really go visit.  I can tell just by looking that you need a break after so many difficult, lucrative adventures.", sourceObjective = "Visit Sassy Hardwrench at Hardwrench Hideaway in the Cape of Stranglethorn.Say, {class}, you look tired. Carrying around that heavy wallet... er, I mean... heavy equipment... must be a strain on your poor {race} back.\n\nSassy Hardwrench has recently established a premier five-star resort on the sparkling coast off the Cape of Stranglethorn. Balloon tours, rowboating, day trips to Booty Bay... they've got it all.\n\nYou should really go visit. I can tell just by looking that you need a break after so many difficult, lucrative adventures.", sourceObjectiveStatus = "unverified-source-field" }
quests[26840] = { id = 26840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Highlands", description = "With Orgrimmar secure and our Dragonmaw allies behind us, we can turn our attention to the conquest of the Twilight Highlands and the utter destruction of Deathwing's forces there.\n\nI need the Horde's best on the front lines. That means you. And all your friends.\n\nThe Highlands WILL be ours!\n\nUse the new portal you created to return to Dragonmaw Port. Report to Zaela to see where she needs you the most.", sourceObjective = "Use the Twilight Highlands Portal in Orgrimmar to return to Dragonmaw Port in the Twilight Highlands and speak to Zaela.", completion = "{name}! I trust Orgrimmar fares well?\n\nAs you can see, construction of Dragonmaw Port continues at a breakneck pace. If my people questioned the Horde's power before... the sight of this imposing edifice and the speed in which it was constructed leaves no doubt.\n\nA new day dawns for the Dragonmaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[26841] = { id = 26841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Sigil", description = "This sigil was given to me by a messenger from our mage trainer, Rhyanda. It seems Rhyanda would have words with you when you have a moment. Read it and bring it to her afterwards.", sourceObjective = "Speak to Rhyanda inside Aldrassil in Shadowglen.", progress = "I'm glad that you've come, {name}.", completion = "I will be your mentor and guide for now. It is my duty to teach you the arcane arts and how you might best fit in among our people.\n\nAs you learn and grow in power, you will learn an immense variety of spells that should allow you to deal with nearly any situation. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26842] = { id = 26842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Gnoll-where", description = "Well met, {class}. We've got a problem, and I'd ask you to lend a hand.\n\nIt's gnolls. There's a mess of the things west of town, roaming the hills. Not usually any cause for alarm, but we've not usually had gnolls here in Loch Modan.\n\nI'm curious where they came from, but not curious enough to bother asking the mangy things. Clear 'em out, I say. Bring back proof of your kills and I'll pay a solid bounty.", sourceObjective = "Collect 12 Gnoll Ears from Mosshide Scouts or Mosshide Bashers.", progress = "Got some ears for me, then?", completion = "Nicely done, lad. I could use a {class} like you around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26843] = { id = 26843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny, Clever Commander", description = "We've dealt with kobolds in these lands for years. Not much other than a nuisance. But they've been getting craftier at their stealing.\n\nI think one of them's ended up smarter than usual. Won't be that way for long, though!\n\nI want you to go to the camp south of here and make sure there's not a \"big shot\" kobold stirrin' up the other ones. Make sure to check the cave; it's a likely spot.\n\nAnd don't be shy about clearing out the other kobolds along the way.", sourceObjective = "Slay Commander Nazrim.", progress = "Don't forget to find that \"commander\" down in the cave.", completion = "So I was right! Now the question is what the little freaks were plotting...", sourceObjectiveStatus = "unverified-source-field" }
quests[26844] = { id = 26844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold and Kobolder", description = "Now that those little blighters are dealt with, we've got more to take care of.\n\nThe tunnel rats are swarming all over the Silver Stream Mine, setting up camps and sniffing around further and further every day. Greedy little things are looking for loot, I gather.\n\nSurveying and foraging is all fine and dandy when it's not on dwarven land! Take care of those tunnel rats and report back to me.", sourceObjective = "Slay 5 Tunnel Rat Surveyors and 5 Tunnel Rat Foragers.", progress = "We'll deal with the mine proper once you've cleaned up the outer perimeter.", completion = "Good, good. Now we can see what's going on down in that mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[26845] = { id = 26845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who's In Charge Here?", description = "Dorli's filled me in on this crazy trogg-slave operation the kobolds have going, and if you haven't talked to her about it yet, I suggest you do.\n\nI'd like to get to the bottom of this. Literally! Whoever's running this show is bound to be at the bottom of the mine, calling the shots, and I want them dealt with.\n\nFind whatever crafty bugger is directing the geomancers and diggers and bring me back their head.", sourceObjective = "Collect the head of Foreman Sharpsneer.", progress = "I don't suppose it was Moira down there? Miracles do happen.", completion = "That's a gnoll head. Are you trying to pull some funny business, {name}?\n\nIf you're not, I've not the faintest idea what's going on here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26846] = { id = 26846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nasty Exploit", description = "I've found out what those rats are up to. There's so many of them outside because they've got troggs digging for them in the mine!\n\nThe tunnel rat geomancers figured out some kind of parlor trick to control the troggs, as creatures of the earth or somesuch.\n\nFascinating, but not something we want to let them practice. Take out those geomancers right away.", sourceObjective = "Slay 5 Tunnel Rat Geomancers.", completion = "I'm sure that only worked because the troggs aren't bright to begin with. But then again, us dwarves were once creatures of the earth as well.\n\nBeing bossed around by a kobold doesn't sound quite dignified, and I'm glad we didn't get to find out if they could pull that off.", sourceObjectiveStatus = "unverified-source-field" }
quests[26854] = { id = 26854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Pilot", description = "My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills. We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot.\n\nIt's been days, and I've heard some beastly growls north of Helm's Bed Lake, west of the tunnel. Mori's tough as nails, but I'm worried.\n\nPlease, {name}. Find him.", sourceObjective = "Find Pilot Hildelve north of Helm's Bed Lake.", completion = "Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers.  Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve.  And around its frame, still in superior condition, is a Brigadier's Vest.\n\nThis grisly scene must have been where the Siege Engine pilot met his end.", sourceObjectiveStatus = "unverified-source-field" }
quests[26855] = { id = 26855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pilot's Revenge", description = "Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\"  He drove off the beast, but not before it mauled him savagely.\n\nJudging from the state of Hildelve's body, Mangeclaw must have later returned and killed him.\n\nHowever, Hildelve wrote in his journal his one, final wish:\n\nRevenge against Mangeclaw.", sourceObjective = "Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot at the South Gate Outpost.", progress = "Hello, {name}.  Do you have word of my friend Hildelve?", completion = "This is grim news, for Hildelve was a good friend.  And I wish I could have been there with you when you found the beast, Mangeclaw!\n\nThank you, {name}. Your deed will be remembered by the pilots of the Ironforge Siege Brigade.", sourceObjectiveStatus = "unverified-source-field" }
quests[26856] = { id = 26856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repel the Invasion", description = "This cavern was once a place of great honor. Young warriors were taken here to slay an Earthborer worm for their first kill - something we Orcs remember for our entire lives.\n\nThe Burning Blade agents inside have enslaved the cave's inhabitants and plan to launch a full-scale attack on Orgrimmar along with their Trogg allies.\n\nIf you strike down their Lieutenants, you may be able to catch them unprepared and stop this invasion before it starts.", sourceObjective = "Kill Oggleflint, Bazzalan, and Jergosh the Invoker.", completion = "You've done it, {name}! You've upturned the Searing Blade's invasion before it could even start! Take this, as a token of my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[26857] = { id = 26857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssion's Minions", description = "If it's the dragon that's got the fragment, we're going to need to draw his attention back to his den.\n\nGo to Abyssion's Lair just east of here and defeat his underlings.  That should get him to show up with the World Pillar fragment sooner or later.", sourceObjective = "Defeat 8 Twilight or Dragonkin units at Abyssion's Lair.", completion = "That ought to get the dragon's attention, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26858] = { id = 26858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taragaman the Hungerer", description = "The Searing Blade has managed to summon a foul demon they call Taragaman the Hungerer to lead the first attack in their takeover of Orgrimmar!\n\nMake haste and slay Taragaman in the name of the Warchief! Lok'tar ogar!", sourceObjective = "Take Taragaman the Hungerer's heart.", progress = "If Taragaman is dead, show me his heart.", completion = "My children will sing songs of your glories, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26860] = { id = 26860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thelsamar Blood Sausages", description = "There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them?\n\nNo? Well, around here you've got to work for your meals, and don't think just because you're a fancy {class}, you'll be any exception.\n\nYou get me some fresh bear rumps and leave the cooking to me!", sourceObjective = "Collect 8 Bear Rumps from Black Bears in Loch Modan.", progress = "I'm all ready to start cooking, do you have the bear meat for me?", completion = "Much obliged! The rump's part of my own secret twist on the recipe... but here's instructions on how to make it with any kind of bear meat.\n\nAnd here's a fresh batch of me own. Mind you eat them fresh!", sourceObjectiveStatus = "unverified-source-field" }
quests[26861] = { id = 26861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Block the Gates", description = "If we're to have a shot against Abyssion, we must make sure he receives no aid from reinforcements.\n\nYou will find two gateways in his lair to the east.  Use this stormstone to disrupt their operation.\n\nIf everything goes as planned, we'll be able to tackle Abyssion without him being able to receive much assistance.", sourceObjective = "Use the Stormstone at the Twilight Gate and Elemental Gate in Abyssion's Lair.", progress = "You've returned, {name}.  Are the gates closed?", completion = "Excellent.  When we make our move against Abyssion, we should be able to do so without reinforcements coming to his aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[26862] = { id = 26862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Tampering", description = "The Searing Blade's warlocks have enslaved Ragefire Chasm's elemental spirits, {name}. They aren't a threat to the city while my spell keeps them at bay, but I can't maintain it much longer.\n\nBring me six of the Searing Bindings used to control them and I will release their spirits back into the Chasm.", sourceObjective = "Obtain 6 Searing Bindings.", progress = "Do you have the bindings?", completion = "Thank you, {class}. The Molten Elementals' spirits are finally back to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26863] = { id = 26863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filthy Paws", description = "The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now kobolds have moved in, putting their filthy paws on good, dwarven tools!\n\nWe'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side.\n\nThe gear is stored in Miners' League Crates throughout the mine.  Good luck.", sourceObjective = "Collect 6 loads of Miners' Gear from the Silver Stream Mine.", progress = "Do you have that Miners' Gear, {name}?", completion = "Did you see a lot of kobolds in there? The thought of their grimy hands clawing around our mine makes my stomach rumble!", sourceObjectiveStatus = "unverified-source-field" }
quests[26864] = { id = 26864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bearer of Gnoll-edge", description = "I need you to take this back to Mountaineer Kadrell. Show it to him and tell him the nasty critters around here might be having some kind of get-together.", sourceObjective = "Deliver Foreman Sharpsneer's Head to Mountaineer Kadrell.", progress = "Any news from Algaz Station?", completion = "Gnolls and kobolds, and troggs? Oh my.\n\nI'd laugh if I didn't have another twist in the story for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26865] = { id = 26865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "There are enemies of the Horde beneath this very city, {class}.\n\nThe Searing Blade plots to take Orgrimmar for their own, and have already taken Ragefire Chasm! We need to storm their forces and retake what is ours!\n\nGo speak with Stone Guard Kurjack just inside Ragefire Chasm. He will have further orders for you.", sourceObjective = "Speak with Stone Guard Kurjack.", completion = "I've been expecting your arrival, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26866] = { id = 26866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Searing Blade. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Stone Guard Kurjack just inside the Chasm. Help him in any way you can, for our fates are intertwined.", sourceObjective = "Speak with Stone Guard Kurjack.", completion = "I've been expecting your arrival, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26867] = { id = 26867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "With all his usual grace, Warchief Garrosh has kindly requested your presence in Ragefire Chasm to help retake it from the Searing Blade. Apparently, his reinforced city isn't as impenetrable as he thought.\n\nGo speak with Stone Guard Kurjack just inside Ragefire, I'm sure he'll be glad to have competent help.", sourceObjective = "Speak with Stone Guard Kurjack.", completion = "I've been expecting your arrival, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26868] = { id = 26868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Axis of Awful", description = "Alright, now just shut yer gob and lemme talk, 'cause here's the plan.\n\nThose gnolls and murlocs are liable to be meetin' out there somewhere. So you take this clever plant disguise of mine, and you wear it and look like a plant. Then you sneak up on 'em, and you throw this scent pheromone you gathered on the mosshide standin' with the murlocs.\n\nThen the murlocs'll flip their spit, and the mosshides will think twice about trying to work with such crazy lil' buggers!", sourceObjective = "Use the Clever Plant Disguise Kit to sneak up on the Mosshide Representative and use the Potent Murloc Pheromones on him.", completion = "Worked like a charm, didn't it? Maybe Kadrell will get off my darn back now what with savin' the whole town and all!\n\nI suppose you've done earned yourself some proper goods.", sourceObjectiveStatus = "unverified-source-field" }
quests[26869] = { id = 26869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Depth of the Depths", description = "<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.>\n\nWell done, {race}.\n\nWithin the tunnels below, you will find the stone which you seek. Painite.\n\nThe dangers ahead are many...\n\nDangers that the Stone Lords themselves fear.\n\nRemain steady.\n\nRemain strong.\n\nThe strength of the rock itself is beneath your feet.", sourceObjective = "Find the Painite within the Crumbling Depths.", completion = "<This is it. This is the stone Diamant sent you for.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26870] = { id = 26870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Caverns", description = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was.\n\nBut something went terribly wrong.\n\nNaralex's trusted allies, the Druids of the Fang, turned on him! They seek not to heal the Barrens, but to dominate it.\n\n{name}, before we can awaken Naralex and restore balance to this vital place, you need to eradicate the Fanglords. Their influence has sunk too deeply.", sourceObjective = "Ebru in the Wailing Caverns wants you to kill the Fanglords Cobrahn, Anacondra, Pythas, and Serpentis.", progress = "Are the Fanglords dead? Muyoh cannot awaken Naralex until they are!", completion = "I can already feel the balance returning! Quick, talk to Muyoh to help him awaken Naralex!", sourceObjectiveStatus = "unverified-source-field" }
quests[26871] = { id = 26871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rock Amongst Many", description = "<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.>\n\nYou've done as I've asked.\n\nTurn back and escape the cave in one piece.\n\nDon't forget the gemstone.", sourceObjective = "Return to Diamant at Lorthuna's Gate with the Painite Chunk.", progress = "You're alive. This is good.\n\nIs the gemstone with you?", completion = "Well done, fleshling!\n\nThe gyreworms are among our most dangerous enemies.\n\nThe other Stone Lords shall have trouble not turning their head to this accomplishment.", sourceObjectiveStatus = "unverified-source-field" }
quests[26872] = { id = 26872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deviate Hides", description = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. Their very existence causes great pain to the earth. I believe that slaying them will greatly aid our work in healing the caverns.\n\nIf you feel up to the task, slay as many as you can and bring me their hides as proof of their demise.", sourceObjective = "Nalpak wants 10 Deviate Hides.", progress = "How many of the beasts have you slain?", completion = "Your efforts shall not go unnoticed, {name}.\n\nThank you for your dedication.", sourceObjectiveStatus = "unverified-source-field" }
quests[26873] = { id = 26873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preemptive Methods", description = "There is an herb in these caverns that holds untold power, {name}. Perhaps you wish to help me collect it?\n\nIt is a rare flower called Serpentbloom. I believe that in greater quantities it has the potential to prevent nightmares like Naralex's from ever occuring.\n\nUnfortunately, Serpentbloom can only be found in the darkest recesses of this place.", sourceObjective = "Nalpak wants you to collect 5 Serpentbloom.", progress = "I am eager to see if you can gather enough Serpentbloom.", completion = "You have done well, {name}. Hopefully we can use these to prevent further nightmares.", sourceObjectiveStatus = "unverified-source-field" }
quests[26874] = { id = 26874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakening Naralex", description = "Now that the Fanglords are dead, speak with Muyoh. He will help you awaken Naralex and end this nightmare.", sourceObjective = "Speak with Muyoh.", sourceObjectiveStatus = "unverified-source-field" }
quests[26875] = { id = 26875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undying Twilight", description = "The Twilight Cultists are here! They're trying to stop the ritual! Get to the back chambers and help fight them off!", sourceObjective = "Kill 12 Twilight invaders and 1 Desecrated Earthrager.", progress = "We cannot let the binding be interrupted. They need your help in the back rooms - please hurry.", completion = "The Twilight forces continue to stream in, but it looks like the Earthen Ring defenders can handle them.", sourceObjectiveStatus = "unverified-source-field" }
quests[26876] = { id = 26876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Pillar Fragment", description = "It is time, {name}.  We have spotted Abyssion making his way to the lair.\n\nThe Twilight's Hammer might've thought the fragment would be safe if a dragon guarded it, but I've met enough dragons to know their one weakness.  Pride.\n\nAbyssion's not going to run from a fight with us puny mortals.\n\nPlace the banner of the Earthen Ring in the middle of his lair.  Once we defeat him, bring the fragment to Maruut.  We need to to repair the World Pillar as soon as possible.", sourceObjective = "Place the Earthen Ring Banner in the center of Abyssion's Lair, slay him and obtain the Upper World Pillar Fragment.", progress = "{name}!  You've returned!", completion = "Your efforts in repairing the World Pillar are invaluable, {name}.  Once the Temple of Earth's structure is stable again, the rift between the worlds will begin to stabilize.", sourceObjectiveStatus = "unverified-source-field" }
quests[26878] = { id = 26878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disciples of Naralex", description = "{class}, the Barrens used to be one of the most beautiful places in all of Kalimdor. It teemed with life and promise.\n\nNow, as you can see, that is no longer true. It is a land of great torment and strife.\n\nThe Disciples of Naralex seek to cleanse the Wailing Caverns and bring them back to their former beauty. Speak with Nalpak just inside the Wailing Caverns to help.", sourceObjective = "Speak with Nalpak in the Wailing Caverns.", completion = "Yes, {class}? What brings you to this place?", sourceObjectiveStatus = "unverified-source-field" }
quests[26881] = { id = 26881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Thaelrid", description = "There's something sinister going on within this place, {name}. We fear that the rumors of the Naga working with the Twilight's Hammer are true.\n\nI sent Thaelrid, one of our best scouts, further in to investigate the matter, but he hasn't returned.\n\nSeek him out. If he's still alive, find out all that he's learned.", sourceObjective = "Seek out Scout Thaelrid.", completion = "Ashelan was good to send you. There is indeed a wicked plot underway in this corrupted place.", sourceObjectiveStatus = "unverified-source-field" }
quests[26882] = { id = 26882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Villainy", description = "My strength has left me. I need your help!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.\n\nAku'Mai, a servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Ashelan.", sourceObjective = "Get the head of Twilight Lord Kelris.", progress = "It is good to see you again, {name}. What news do you bring?\n\nWas your foray successful? Did you find Thaelrid?", completion = "Kelris has eluded us for quite some time.\n\nIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him either dead or missing.\n\nBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.\n\nTo sacrifice someone to a servant of an Old God for one's personal gain is beyond reproachful!\n\nYou have done a great deed, {name}. I thank you on behalf of Ashenvale.\n\nIf only Thaelrid had survived....", sourceObjectiveStatus = "unverified-source-field" }
quests[26883] = { id = 26883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods, the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing here.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", sourceObjective = "Obtain 10 Twilight Pendants.", progress = "Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight's Hammer.\n\nHave you made any progress in ridding the temple of their presence?", completion = "You are no doubt of brave and noble blood, {name}. We and all of the people of Ashenvale commend you for your efforts against evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[26884] = { id = 26884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the sin'dorei are headed toward. Try to avoid harming the stems while you kill them, I won't take anything but perfect specimens.", sourceObjective = "Gather 8 Corrupt Brain Stems.", progress = "Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.\n\nPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.", completion = "You have undoubtedly faced great peril to obtain these.\n\nYour actions have been selfless. It is for the good of all Azeroth that you help me with my research. I thank you, {name}, for all that you have done.\n\nNow if you'll excuse me I have much work to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[26885] = { id = 26885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge in the Deeps", description = "It is my duty as a trainee to collect lore for my superiors. Old lore. Powerful lore. Lore that opens doorways, and lore that could awaken more of Those Who Sleep if it is mishandled.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of the Pool of Ask'ar in a Pitted Iron Chest. It is the old dwelling of our long-dead ancestors. They held great knowledge before their city fell to ruin.\n\nSearch for the manuscript, please. I'm not skilled enough to venture further!", sourceObjective = "Find the Lorgalis Manuscript.", progress = "Your task is not an easy one, my friend.\n\nBut if you get me the manuscript, {name}...then your reward will be great and we will gain a better understanding of what it is that the Twilight's Hammer and the naga are up to.", completion = "You found the manuscript! What a joyous day this is! I will study it exhaustively and learn all there is to know.\n\nI'll make full sentinel yet!\n\nYour service to us is more than you know, {name}. I hope that this gift shows you my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[26886] = { id = 26886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Off-Task", description = "That nasty ship on the east side of the cove keeps firing its cannons at us. It's kinda funny seeing all the goblins get hit by cannonballs, but some of my gnome friends are being hit too!\n\nIt'd be really, really nice if you could make your way past those cannons and onto the ship. There's a mean ol' taskmaster yelling at the other deckhands in there, and I'm sure if you beat him up or kill him, they'll stop shooting at us!", sourceObjective = "Kill the Southsea Taskmaster.", completion = "Wonderful! I hope you didn't get hit with too many cannonballs.", sourceObjectiveStatus = "unverified-source-field" }
quests[26887] = { id = 26887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling Our Pockets", description = "I know we're here to make friends with the Steamwheedle goblins, but those awful Bilgewater goblins are so rude\n\nWhy, I just saw a bunch of them pulling gold fillings out of the teeth of the Southsea musketeers and strongarms. Do they think they can just take that for themselves?\n\nObviously, the nice thing to do is kill those pirates ourselves, take their fillings ourselves, and then give some of them to the Steamwheedle as a thank-you gift! Head on down there and beat those goblins to the punch.", sourceObjective = "Collect 20 Gold Fillings from Southsea Musketeers or Southsea Strongarms.", progress = "Have you got the fillings?", completion = "More gold! We'll be sure to give some of this to Mister Noggenfogger to smoothly ensure our continued relations.\n\nAnd only a little bit of it will go back to Gnomeregan for experimental weapons development!", sourceObjectiveStatus = "unverified-source-field" }
quests[26888] = { id = 26888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare of the Deeps", description = "In the darkest recesses of Blackfathom, a monster spawned by the Old Gods lurks. We know it only as Aku'mai.\n\nThe Old Gods and their servants are incredibly dangerous to our world. Long ago, they ruled over Azeroth and I fear that they seek to do so again, or destroy it while trying.\n\n{name}, Aku'mai is a creature of untold nightmare. We simply cannot allow his continued existence. Destroy him.", sourceObjective = "Kill Aku'mai.", completion = "The beast is slain. I can feel his dark presence fading away forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[26889] = { id = 26889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Cheered Out", description = "Well gosh, we've cleaned up quite a bit here!\n\n<Kelsey clears her throat.>\n\nListen, {name}, I'm looking forward to finally vacating this killbox so I can get away from these goblins and drop the cheer-act. If you'd like to continue to advance the interests of Gnomeregan, and by extension the Alliance, in the area, head south to Bootlegger Outpost.\n\nTalk to Zeke Bootscuff there, and remember that any work for the Steamwheedle will help us shut the Bilgewater out of Tanaris for good.", sourceObjective = "Talk to Zeke Bootscuff at Bootlegger Outpost.", completion = "You know, I'm usually not impressed when I see a {race}, but I've heard about what you've been doin' for the Steamwheedle. You're alright, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[26890] = { id = 26890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Aku'Mai", description = "Within the beginning tunnels of Blackfathom Deeps, there are large sapphire clusters along the cave walls. We noticed that the naga started harvesting the crystals around the same time their weaponry greatly improved.\n\nThe crystals seem to have great elemental power and, if used inappropriately, could make for a powerful component for my smithing.\n\nWill you help me, {name}? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", sourceObjective = "Collect 20 Sapphires of Aku'Mai.", progress = "How goes your search for the crystals, {name}? Do you think they'll make an item we can use to stop the naga?", completion = "Excellent! These will do nicely. Here's a reward for your hard work.", sourceObjectiveStatus = "unverified-source-field" }
quests[26891] = { id = 26891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amongst the Ruins", description = "The Twilight's Hammer has moved into the Moonshrine Ruins here.  Their presence can only serve to coerce the elements into working against us.\n\n{name}, find the Twilight agents here, then find the ruin's fathom stone; it should be somewhere underwater, probably right underneath their own noses. In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, the Earthen Ring and I can hopefully do something to stop them!", sourceObjective = "Extract the Fathom Core.", progress = "Have you been successful in locating the fathom core?  Without it we'll have no idea what the Twilight's Hammer is exactly up to down there.", completion = "This is exactly what I need!  A fathom core is an incredible well of information that we will be able to draw much good from.  Whatever the Twilight's Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.\n\nYou've done well here today; the Earthen Ring looks upon you warmly for assisting us.  You've also helped the Horde as a whole, and for that you should be proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[26892] = { id = 26892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep in the Deeps", description = "The Naga and the Twilight's Hammer work together to undo all the progress we've made in this area. What's more, Je'neu tells me that he feels the presence of an Old God lingering far beneath us.\n\nIf they wish to witness chaos, we will give them just that.\n\n{name}, cut down their strongest warriors, and we'll see how much they enjoy it.\n\nSearch carefully, Blackfathom Deeps is full of underwater passages and side paths in the caves that may hide your targets.", sourceObjective = "Slay Ghamoo-Ra, Lady Sarevess, and Gelihast.", progress = "Tell me, {name}, are they like running in panic? They get exactly what they deserve.", completion = "I can hear their cries from here! Maybe this will show them how foolish it is to wish for the return of an Old God.", sourceObjectiveStatus = "unverified-source-field" }
quests[26893] = { id = 26893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "There's a task to be done that you're perfect for, {class}. We need to secure the area around Blackfathom Deeps to help with that Alliance that are threatening Zoram'gar Outpost west of here.\n\nGo to Blackfathom Deeps, north of Zoram'gar Outpost, and speak with Je'neu of the Earthen Ring. He will have plenty for you to do.", sourceObjective = "Speak with Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[26894] = { id = 26894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "The naga mock us with their defiance. We will drive them and their allies out of this land for good.\n\nTravel north of here to Blackfathom Deeps and speak with Je'neu Sancrea. He's already made his way inside.\n\nBe wary of Zeya, by the way. She can be a bit...temperamental at times.", sourceObjective = "Speak with Je'neu Sancrea.", completion = "Did Commander Grimfang send you? I've asked him to find suitable recruits to aid me here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26895] = { id = 26895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunderdrome!", description = "Hey, friend, you interested in excitement? Adventure? Money? Violence?\n\nWell, you'd better like violence, because they just reopened the Thunderdrome in Gadgetzan. It was sad to see it unused for so long, what with the injury lawsuits, and the racketeering charges, and the copyright infringement... But it's back, and just waiting for burly, savage folk like you to enter and throw down with the foulest opponents ever!\n\nHead to Gadgetzan and talk to Dr. Dealwell to sign up. And tell your friends!", sourceObjective = "Talk to Doctor Dealwell in Gadgetzan.", completion = "Another proud {class}, lured by the promise of fame! Of wealth! Of VIOLENCE!\n\nYes, welcome, friend. Welcome... to THUNDERDROME!", sourceObjectiveStatus = "unverified-source-field" }
quests[26896] = { id = 26896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunderdrome!", description = "Hey, friend, you interested in excitement? Adventure? Money? Violence?\n\nWell, you'd better like violence, because they just reopened the Thunderdrome in Gadgetzan. It was sad to see it unused for so long, what with the injury lawsuits, and the racketeering charges, and the copyright infringement... But it's back, and just waiting for burly, savage folk like you to enter and throw down with the foulest opponents ever!\n\nHead to Gadgetzan and talk to Dr. Dealwell to sign up. And tell your friends!", sourceObjective = "Talk to Doctor Dealwell in Gadgetzan.", completion = "Another proud {class}, lured by the promise of fame! Of wealth! Of VIOLENCE!\n\nYes, welcome, friend. Welcome... to THUNDERDROME!", sourceObjectiveStatus = "unverified-source-field" }
quests[26897] = { id = 26897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "Although our position is exposed, we are safe compared to our friends inside Blackfathom Deeps! They stand mere feet away from the most deadly naga forces in the area. Speak with Sentinel Aluwyn and give them the aid they desperately need!", sourceObjective = "Speak with Sentinel Aluwyn.", completion = "Thank Elune you're here! We could use all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[26898] = { id = 26898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "I care deeply about these forests, {class}. Things look grim here, but I would rather face the Horde alone than watch them hack and slash their way through the trees.\n\nTravel west to Blackfathom Deeps. Once you're inside, find Sentinel Aluwyn. She's a trusted friend in need of help.\n\nThe orcs in Zoram'gar Outpost threaten her position as we speak. If they take Blackfathom, they will surely cut every tree down to fuel their insanity.", sourceObjective = "Speak with Sentinel Aluwyn.", completion = "Thank Elune you're here! We could use all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[26899] = { id = 26899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of My Enemy", description = "Cultists...sacrifice...power...\n\nEnemy...awaken...\n\nOld God...imprison...me...\n\nLord...Kelris...\n\nBring head...revenge...\n\nERADICATE!!!", sourceObjective = "Obtain the head of Twilight Lord Kelris.", progress = "Revenge...reward...", completion = "<The Flaming Eradicator appears to concentrate.>\n\nI spare your life for your help, {race}. Leave now...before I change my...mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26901] = { id = 26901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going, Going, Guano!", description = "The bats native to Razorfen Kraul produce a very peculiar natural substance. Their guano's stench seems to send the Quilboar into a murderous frenzy - and this place reeks of it!\n\nI need you to find the bat cave, and bring me a suitable sample. If we can reverse the effects and produce an antidote, we may be able to save the Quilboar.", sourceObjective = "Extract 1 pile of Kraul Guano.", progress = "Ah, I see you have returned. Were you able to procure any Kraul Guano?", completion = "Well done! This is just what we need, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26903] = { id = 26903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willix the Importer", description = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that pig snouts were selling outrageously high in the market. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.", sourceObjective = "Escort Willix the Importer to the exit of Razorfen Kraul.", completion = "Thanks again, friend! I told you I'd make it worth your while.", sourceObjectiveStatus = "unverified-source-field" }
quests[26904] = { id = 26904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harnessing the Flames", description = "Few people, especially among our allies, truly understand the nature of the power we wield. They shun us for pursuing knowledge that they are too weak to use properly.\n\nLet me show you a conjuration that I find handy. This spell, called Immolate, sets your target aflame, causing damage immediately and over time. Use it well, {name}, and your enemies will come to fear you.", sourceObjective = "Speak to Saripal Smolderbrew and learn Immolate, then cast Immolate 5 times on a Training Dummy near the entrance to Anvilmar.", completion = "As you continue to gain power, return to me and I will teach you new spells and techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26905] = { id = 26905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggan's Charge", description = "Listen closely, mortal.\n\nThe Quilboar are my children. My blood runs deep in these lands.\n\nCharlga Razorflank has steered my children into darkness, driven into insanity by the Scourge.\n\nSlay her, {name}. Slay her and open my childrens' eyes.\n\nGive the Quilboar the chance to return to their noble roots. Let them once more earn my blessing.\n\nBring me her heart!!!", sourceObjective = "Take Charlga Razorflank's heart.", progress = "<The Spirit of Agamaggan stares at you patiently.>", completion = "Take this gift. You have earned my blessing this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[26906] = { id = 26906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggan", description = "I sense a being of immense power within these twisted thorns, {name}. The entire area has come alive at its presence.\n\nIt must be the Spirit of Agamaggan! He was one of the first and most powerful beings to ever live - the Quilboar worship him fervently.\n\nAll the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients.\n\nIf there's any being that could steer the Quilboar towards their noble roots, it would be him.\n\nYou must seek him out.", sourceObjective = "Talk to the Spirit of Agamaggan.", completion = "<The Spirit of Agamaggan looks at you. An ancient voice echoes inside your head.>\n\nI've been waiting for you to come here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26907] = { id = 26907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Them Down!", description = "Overlord Ramtusk and the Death's Head mobilize for war. It took many scouts' lives, but we have learned of the weapon they intend to use to overtake the rest of the Barrens.\n\nIt is known as Agathelos the Raging, an immense boar outfitted with heavy armor and force-fed the rage-inducing Kraul bat guano.\n\n{race}, you must stop them before they take innocent lives!", sourceObjective = "Kill Aggem Thorncurse, Death Speaker Jargba, Overlord Ramtusk, and Agathelos the Raging.", completion = "You've done well this day. Agathelos would have taken many lives in its fury.", sourceObjectiveStatus = "unverified-source-field" }
quests[26908] = { id = 26908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeling Thorny", description = "Mankrik's furor over his dead wife raises further concerns , {class}.\n\nThe quilboar in Razorfen Kraul are far more ruthless and full of hatred than Mankrik could ever imagine.\n\nYou should travel south there and speak with my old friend Auld Stonespire. He works to put an end to their rampage before the land suffers more in its already weak condition.", sourceObjective = "Speak to Auld Stonespire.", completion = "Only a veteran like you could brave the dangers lurking here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26909] = { id = 26909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone Shards", description = "Ancient stones are strewn across this land. The elements flock to them, surrounding them protectively.\n\nThese are sites of great power, and the largest is just west of Hammerfall. Not a soul trespasses, but if you go there alone, you can hear whispers from the earth itself.\n\nI have not visited there in a long while... but our grunts have told me the whispers have started again. Would you look for me? Will you see if the stones still speak?", sourceObjective = "Investigate the Shards of Myzrael.", completion = "<The shards pulse softly, and a whisper slowly echoes through your head.>\n\nHelp...", sourceObjectiveStatus = "unverified-source-field" }
quests[26910] = { id = 26910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etched Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Ashley Blank, our local hunter trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", sourceObjective = "Read the Etched Letter and speak to Ashley Blank in Northshire Valley.", progress = "Hello, {name}. Is there something I can do for you?", completion = "So you received my note? Excellent. You've proven yourself quite capable in dealing with those orcs. As you continue to grow in power, I will teach you some new techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26911] = { id = 26911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzrael's Tale", description = "As the stone goes quiet, you're left with a vague sense of unease. Something isn't right.\n\nPerhaps you should tell Zaruk of what you've done so far.", sourceObjective = "Return to Zaruk at Hammerfall in Arathi Highlands.", completion = "I know, {name}. I should not have sent you.\n\nForgive me... the whispers of the past are sometimes too strong.", sourceObjectiveStatus = "unverified-source-field" }
quests[26912] = { id = 26912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess Unleashed", description = "Myzrael is a deceiver. She is an ancient force sealed long ago, and must be kept that way.\n\nYou must confront her at the Shards of Myzrael where you first spoke with her.  Summon her with this scroll, and when she has been fully brought to the surface, defeat her. Then take the Eldritch Shackles from her body and place them on the Shards to keep her fully bound once more.\n\nGood luck, {name}... may my past trouble you no more.", sourceObjective = "Summon and defeat Myzrael at the Shards of Myzrael.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface.", sourceObjectiveStatus = "unverified-source-field" }
quests[26913] = { id = 26913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charging into Battle", description = "Now that you've had the chance to test your abilities in battle, it's time to show you a new combat technique -- charge. As a warrior, it's important to use every advantage at your disposal to get the upper hand in battle.\n\nWhat better way to do that than by charging into battle and stunning your opponent? I'll show you how it's done, and then I want you to go try it on one of the training dummies south of the entrance to the abbey.", sourceObjective = "Speak to Llane Bershere and purchase the Charge ability, then practice using Charge on a Training Dummy south of the entrance to Northshire Abbey.", progress = "Well, did you give it a try?", completion = "You're a quick learner, {name}. Return to me as you grow stronger and I'll show you other combat techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26914] = { id = 26914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immolation", description = "We must take care in how we speak around the abbey and its environs, but don't let that deter you from the path of power.\n\nI want to show you one of my favorite spells. It will allow you to set an opponent on fire, damaging the enemy immediately and continuing to do more harm over time.  I'll show you how it's done, and then I want you to go try it on one of the training dummies south of the entrance to the abbey.", sourceObjective = "Speak to Drusilla La Salle and purchase the Immolate ability, then practice casting Immolate 5 times on a Training Dummy south of the entrance to Northshire Abbey.", progress = "Well, did you give it a try?", completion = "I see you have already mastered Immolation! I look forward to instructing you in the future. Do not forget to return for further lessons as you grow in power.", sourceObjectiveStatus = "unverified-source-field" }
quests[26915] = { id = 26915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deepest Cut", description = "By now, you know the basics of combat as rogue, but I want to teach you a new skill. As rogues, we are renowned for our ability to execute chains of combat techniques, often saving the most powerful strikes for the end.\n\nLet me show you the basics of Eviscerate. After using Sinister Strike a few times, you can attack with Eviscerate to hit your opponent even harder. I want you to go try it on one of the training dummies south of the entrance to the abbey.", sourceObjective = "Speak to Jorik Kerridan and purchase the Eviscerate ability, then find a Training Dummy south of the entrance to Northshire Abbey and practice Eviscerate 3 times.", completion = "You've caught on quickly, {name}, and a quick mind will serve you well. Return to me as you grow in power and I will show you new techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26916] = { id = 26916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Arcane", description = "As a mage, you will learn a variety of spells as your understanding grows. I want to show you a new technique that allows you to launch volleys of arcane energy at your opponent, Arcane Missiles. You won't be able to cast this spell all the time, but each time you cast another spell, there's a chance you'll create an opening to use Arcane Missiles.  I'll show you how it's done, and then I want you to go try it on one of the training dummies south of the entrance to the abbey.", sourceObjective = "Speak to Khelden Bremen and purchase the Arcane Missiles ability, then practice casting Arcane Missiles 2 times on a Training Dummy south of the entrance to Northshire Abbey.", progress = "Well, did you give it a try?", completion = "Have you mastered the use of Arcane Missiles already? You are a quick study in the arcane arts and you have a promising future ahead. Don't forget to return to me for training as you grow in power.", sourceObjectiveStatus = "unverified-source-field" }
quests[26917] = { id = 26917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "I've heard about your help in clearing out some of the orcs. You've shown that you can handle yourself in combat.\n\nI want to show you a new skill.  I'll show you how it's done, and then I want you to go try it on one of the training dummies south of the entrance to the abbey.", sourceObjective = "Speak to Ashley Blank and purchase the Steady Shot ability, then find a Training Dummy south of the entrance to Northshire Abbey and practice using Steady Shot 5 times.", progress = "Well, did you give it a try?", completion = "I knew you would master Steady Shot quickly. I'm looking forward to showing you other techniques as you get more experienced in the ways of the {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26918] = { id = 26918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of the Light", description = "I want to teach you a couple of techniques for using the Light's power to boost your combat skills.\n\nThe first technique is applying the Seal of Righteousness. While under the effects of the seal, all of your melee attacks will inflict additional holy damage.\n\nThe second ability, Judgement, can be use periodically to unleash the seal's power and inflict damage.", sourceObjective = "Speak to Brother Sammuel and purchase the Seal of Righteousness and Judgement abilities. Cast Seal of Righteousness on yourself and then use Judgement on a Training Dummy south of the entrance to Northshire Abbey.", progress = "Well, did you give it a try?", completion = "You're a quick learner, {name}. Return to me as you grow stronger and I'll teach you more about using the Light to vanquish your enemies and strengthen your allies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26919] = { id = 26919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing the Wounded", description = "One of your responsibilities as a priest is caring for the wounded. With the power of the Light, you can save those who would otherwise die and speed the healing of wounds.\n\nI want to teach you a simple, quick technique you can use to heal an ally quickly.\n\n I'll show you how it's done, and then I want you to use this spell to treat the injuries of wounded trainees around the abbey.", sourceObjective = "Speak to Priestess Anetta and purchase the Flash Heal ability, then use Flash Heal 5 times to treat Wounded Trainees inside Northshire Abbey.", progress = "Have you tended to the wounds of the injured?", completion = "You're a quick learner, {name}, and the wounded are fortunate to have your aid. Return to me as you grow stronger and I'll teach you other spells.", sourceObjectiveStatus = "unverified-source-field" }
quests[26920] = { id = 26920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "Hurry, {name}... there isn't time to waste.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  Lady Sylvanas has sent one of her best death knights to lead the charge for her cause, but I'm sure he can use all the help he can get.  With Arthas dead, now is the perfect time for the Forsaken to take Andorhal.\n\nSpeak with the bat handler, Timothy Cunningham, when you are ready, and he will put you on the first flight out there.", sourceObjective = "Report to Koltira Deathweaver within Andorhal in Western Plaguelands.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26921] = { id = 26921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge First... Alliance Later", description = "Darkmaster Gandling of the Cult of the Damned leads the Scourge offensive here in Andorhal.  My old counterpart, Thassarian, leads the Alliance forces.  If we're to win Andorhal, we'll have to defeat both, but we will certainly fail if we take on both at once.\n\nI know Thassarian well enough to know that he will focus on the Scourge first.  We will do the same.\n\nTake out the weaker, desiccated Scourge to reduce their numbers.  The Alliance will have to wait to taste our wrath.", sourceObjective = "Slay 15 Desiccated Scourge within Andorhal.", completion = "You may not act quickly, but at least you do not fail me.\n\nVery well.  I will have a more important task for you, {name}, when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[26922] = { id = 26922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Flow", description = "Araj the Summoner is bolstering the Scourge defenses with simple skeletons... an army of weaklings that will overwhelm you before it overpowers you.  He has assembled animi within Andorhal's northern towers that spew these skeletons out at an alarming rate.  But I've got the solution!\n\n<Jearl passes you a handful of grenades.>\n\nTheir function is simple.  Throwing these grenades at a bone animus... or, for that matter, a mob of skeletons... will reduce them to splinters.", sourceObjective = "Use Jearl's Hand Grenades to kill 5 Stickbone Berserkers and to destroy a Scourge Bone Animus.", completion = "These grenades are all explosives, nothing more.  Even as a member of the Royal Apothecary Society, I recognize that some problems are not solved by throwing more plague at them.", sourceObjectiveStatus = "unverified-source-field" }
quests[26923] = { id = 26923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Machines", description = "You fools will never defeat the Scourge with those abominations running around.  Koltira blathers on about reducing their numbers, but the Scourge's best weapon here in Andorhal can be found in those lumbering brutes that are throwing my deathguards around like ragdolls.\n\nI won't have it.  {name}, enter the battlefield and destroy those monsters.", sourceObjective = "Destroy 6 Opengut Behemoths in Andorhal.", completion = "With the behemoths out of the way, our victory against the Scourge is inevitable.\n\nOur current chances against the Alliance aren't quite as favorable... but that's no concern of yours.  Not yet, anyhow.", sourceObjectiveStatus = "unverified-source-field" }
quests[26924] = { id = 26924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "The Scholomance is one of the few Scourge holdouts remaining west of the Thondroril.  The headmaster of Scholomance, a cultist by the name of Darkmaster Gandling, has made an appearance on the battlefield.\n\nThis will be his final mistake.\n\nYou will find Gandling in a square near the southern end of town.  I want you to fight and weaken Gandling.  I will join you to help finish him off.", sourceObjective = "Kill Darkmaster Gandling within Andorhal.", completion = "Excellently done, {name}.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26925] = { id = 26925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj the Summoner", description = "With the animus destroyed, the next logical step is to take out Araj himself, and to take a shard of his phylactery.  You've probably already seen him, lurking at the fountain in the center of town.\n\nTake my grenades with you.  They won't do anything to Araj, but if he decides to summon any of those skeletons, you can use them to blow them away.  Again.", sourceObjective = "Kill Araj the Summoner. You may use Jearl's Hand Grenades to destroy Stickbone Berserkers.", progress = "Araj is a formidable opponent.  Be prepared.", completion = "Araj dead... this is good.  The Royal Apothecary Society has done its part.  As have you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26926] = { id = 26926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory, For Now", description = "The Forsaken are victorious, and our forces are still strong.  Military strategy dictates that we attack the Alliance now, while they are recovering and unaware.  I have other plans, however...\n\nWe will wait.  We attack Thassarian and his troops when the time is right.  In the meantime, speak with Rhonda Molver and take a flight to the Bulwark, on the Plaguelands' western border.  High Executor Derrington will give you your next assignment.\n\nYou will hear from me when you are needed again in Andorhal.", sourceObjective = "Report to High Executor Derrington at the Bulwark in Tirisfal Glades.", completion = "Word arrived shortly before you did, {name}.  With the Scourge ejected from Andorhal, the Forsaken has cemented its foothold in Lordaeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[26927] = { id = 26927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suddenly, Murlocs!", description = "So we've got troggs working for kobolds, and kobolds working for gnolls. The gnolls must've moved in from the Wetlands.\n\nHow do I know? Well, they brought friends, because what's left of the Loch is swarming with Bluegill murlocs that were never there before.\n\nPests are pests, but this coordination is worrying. I need you to talk to Cannary Caskshot. She's one of the best hunters in these parts, and she'll know how to handle murlocs, if you can pull her away from her mug long enough.", sourceObjective = "Speak with Cannary Caskshot.", completion = "Murlocs? Sure, I've hunted murlocs.\n\nAnd every single stinkin' one of them deserved what they got! You hear me?", sourceObjectiveStatus = "unverified-source-field" }
quests[26928] = { id = 26928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smells Like A Plan", description = "Murlocs workin' with gnolls? That's a laugh! Now, just killin' them won't get you anywhere. Too many of the buggers.\n\nBut I've got a plan, usin' the old noggin, see. Those murlocs, they have this smell, they get that smell on stuff, and when another murloc smells it, they go all crazy! Makes great bait for 'em.\n\nAnyway, they've got little glands that have that smell in 'em. You go and get me a bunch of those.", sourceObjective = "Collect 7 Murloc Scent Glands from any Bluegill Murloc in The Loch.", progress = "Now don't you stink all to high hell! I'm assumin' that's because of the murlocs, but it's hard to tell.", completion = "Phew! Ain't that a stench.\n\nNow you prepare yourself, because I'm about to wow you with what's left of my mental faculties.", sourceObjectiveStatus = "unverified-source-field" }
quests[26929] = { id = 26929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Load of Croc", description = "Now while you're runnin' around doin' whatever the heck it is that you do, would you mind helpin' me out a bit?\n\nSee, I usually go out huntin' crocolisks down in the loch, but given certain circumstances, I'd rather sit here right now. Mighty polite of you not to give me grief over it, thanks!\n\nSo seein' as how you're such a <gentleman/lady>, why don't you bring me back some crocolisk jaws and I'll give you some mostly-clean money in return.", sourceObjective = "Collect 6 Crocolisk Jaws.", progress = "So did you get those crocolisk things or did I make that up?", completion = "Mighty kind of you to help out an ol' fool like me. Here's your reward as promised an' all.", sourceObjectiveStatus = "unverified-source-field" }
quests[26930] = { id = 26930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After the Crusade", description = "Our victories are quickly piling up, {name}.  The Scarlet Crusade, which has long persecuted the Forsaken, is on its last legs.  While they still hold their monastery here in Tirisfal, they no longer occupy Hearthglen, or Tyr's Hand, far to the east.\n\nAs recently as last week, there have been reports of Scarlet Crusade activity at a small camp east of Felstone Field, but I have reason to believe that they too have been eliminated.  Travel there, and verify this information for me.", sourceObjective = "Scout the Scarlet Crusade camp located east of Felstone Field in Western Plaguelands.", completion = "Burning bodies?  No survivors?  I guessed correctly.\n\nAll the better!  We're better off without the Scarlet taint upon Lordaeron.  They epitomized all the worst things about humans.", sourceObjectiveStatus = "unverified-source-field" }
quests[26931] = { id = 26931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foxes and Hounds", description = "These Alliance forces walk around the Plaguelands like they own the place.  Well, they don't!  This land rightfully belongs to the Dark Lady!\n\nAs the battle for Andorhal drew to a close, the Alliance forces occupying the Plaguelands scattered.  Several of them can be found just east of here, hunting foxes.  Prove to them that this is Forsaken territory.\n\nKill the hunters.  Kill their hunting dogs.  And kill the foxes they hunt, for good measure.", sourceObjective = "Kill 4 Alliance Fox Hunters, 4 Bullmastiffs, and 4 Whitetail Foxes in Western Plaguelands.", completion = "It's a relief to have those hunters out of the way.  We're not done killing Alliance, however...", sourceObjectiveStatus = "unverified-source-field" }
quests[26932] = { id = 26932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzz Off", description = "When the Stonewrought Dam burst, it drained near the entire loch. Horrible ecological devastation.\n\nAnd don't you go thinking it didn't really affect us dwarves! Not only are we plumb out of fish, but there's acres of dead threshadons out there left to rot in the sun. The buzzards are after them, and they're spreading all manner of filth and disease right on the outskirts of town.\n\nI can't ask you to clean it all up, but could you deal with the buzzards? Killin' even just a few will help.", sourceObjective = "Kill 8 Loch Buzzards.", completion = "That should help prevent disease and illness from spreading into our remaining water. Many thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26933] = { id = 26933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foes Before Hoes", description = "The men who till Felstone Field are no farmers.  They're soldiers.\n\nThassarian's forces needed food, so he sent some of the Alliance north from Andorhal, to tend Felstone Field.  The battle for Andorhal may be over, but another battle looms... Forsaken versus human.  Killing those soldiers that work at Felstone will give the Dark Lady's forces a decided advantage.", sourceObjective = "Kill 9 Alliance Laborers on Felstone Field.", completion = "Ha ha!  I hope that they come back as zombies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26934] = { id = 26934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latent Disease", description = "I need plagued grass for an... an experiment, of sorts.  Those Argent Crusaders and those infernal Cenarion druids have done too good a job of healing the plaguelands, however... and I can't find proper reagents within a reasonable walking distance.\n\nSome of the local wildlife retain the plague's touch, however.  Kill a diseased black bear, then retrieve the grass that grows where its decaying body lies.  It's not optimal, but it'll do.", sourceObjective = "Kill Diseased Black Bears in Western Plaguelands, then loot 20 Plague Tangles that grow near their corpses.", progress = "Animal tissue holds onto disease so much better than plant tissue, doesn't it?", completion = "Glorious!  This is the last bit I need.\n\nActually, stick around, {name}.  Let me tell you a little bit more about our plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26935] = { id = 26935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northridge Lumber Mill", description = "We are not the only Argent Crusaders here in the plaguelands.  Our headquarters, Hearthglen, lies to the north.  Even nearer to the north is a small lumber mill which we also control.\n\nNathaniel Dumah is my main contact at the lumber mill.  I encourage you to speak with him, should you find yourself in that part of the woods.", sourceObjective = "Report to Nathaniel Dumah at the Northridge Lumber Mill in Western Plaguelands.", completion = "Welcome to Northridge, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26936] = { id = 26936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower the Boom", sourceObjective = "Felstone is cleared and the bombs are set.  I hope you're ready.  I recommend covering your ears.\n\n<Derrington looks down and places his finger on an ignition switch.>\n\nEVERYBODY, PREPARE FOR IGNITION!  IN 3...\n\n2....\n\n1...", sourceObjectiveStatus = "unverified-source-field" }
quests[26937] = { id = 26937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Death is Not Enough", description = "Derrington and his men don't know it, but it was I who ordered the plaguing of Felstone Field.  We need this area for practice.  If we're to win this war for Andorhal, we need to use our newest, most versatile weapon:\n\nVal'kyr.\n\nTake my enthralled val'kyr with you, {name}, and kill the simpering Alliance scum that remain on Felstone.  Once they are dead, she will bring them back to this world... as one of us.\n\nThe Forsaken shall not die out!", sourceObjective = "Kill 8 Alliance Laborers on Felstone Field so your Enthralled Val'kyr can convert them into Forsaken.", completion = "I am able to communicate with you through the Val'kyr, {name}.  You have done well.\n\nRemain on Felstone Field.  We must now teach these newly-converted Forsaken how to fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[26938] = { id = 26938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "A val'kyr's only purpose is to serve, and this one serves you.  I am now giving you full control over her abilities, {name}.\n\nRoaming around the farm's outskirts, you should find several of the Forsaken that you just created.  I want you to use your val'kyr to gather at least five of them.  Once you have done so, take your newly-formed band of soldiers, bring them into Felstone's barn, and kill the beast inside.  Today, they will learn what it means to fight for the Dark Lady.", sourceObjective = "Use your Enthralled Val'kyr's Call to Arms ability to mobilize 5 Forsaken Troopers on Felstone Field. Then slay the Opengut Abomination inside Felstone's barn.", completion = "When Koltira gives his word, I will bring these val'kyr into Andorhal.  We will win.  And yet another piece of Lordaeron will fall to the might of the Forsaken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26939] = { id = 26939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "How did you get in here?\n\nOh, it doesn't matter. I'm Murd Doc of the G-Team. We're the best there is, and we're here to retake Gnomeregan!\n\nWhen nobody else could help him, the High Tinker found and hired us.\n\nBut we simply can't do this alone! You're an honorary G-Team Commando now, {name}.\n\nTake this parachute, jump down straight ahead into the Hall of Gears, and kill the Viscous Fallout. After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.", sourceObjective = "Kill the Viscous Fallout.", completion = "I hope that wasn't too much for you. The mission is far from over!", sourceObjectiveStatus = "unverified-source-field" }
quests[26940] = { id = 26940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Missiles", description = "We are the heirs to a legacy of arcane magic and your path will not be an easy one. Many still hold us responsible for the actions of our forebears, but our talents are needed.\n\nI want to show you a new spell, Arcane Missiles. It allows you to fire volleys of arcane energy, but you won't be able to cast it all the time. Casting other spells has a chance to create an opportunity for you to use Arcane Missiles.\n\nI want you try it. Look for a training dummy near the southeastern edge of Aldrassil.", sourceObjective = "Learn Arcane Missiles from Rhyanda. Look for a Training Dummy near, and practice using Arcane Missiles twice.", completion = "I knew you would master this lesson quickly. You are a credit to the highborn and to all our kin. Remember, as you grow in power, return to me and will instruct you further.", sourceObjectiveStatus = "unverified-source-field" }
quests[26941] = { id = 26941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "That Murd Doc is crazy, {class}. Never, ever, let you find yourself in an aircraft with that gnome.\n\nStealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000.\n\nThe Electrocutioner is in charge of the aircraft...\n\n...and I hate aircraft. I'm not getting in any sort of aircraft!\n\nUse this parachute to drop down afterwards and speak with Commando Face for your next job.", sourceObjective = "Kill the Electrocutioner 6000.", completion = "Took you long enough. Get behind the pillar with me before you blow our cover!", sourceObjectiveStatus = "unverified-source-field" }
quests[26942] = { id = 26942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable.\n\nYou are, though, so let's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg.\n\nOur leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work.\n\nProbably.", sourceObjective = "Kill Mekgineer Thermaplugg.", completion = "I'd love for you to come aboard as a full G-Team Commando, but you have other adventures to pursue.\n\nI'm sure we'll meet again, and I hope you'll have considered joining by then. Here's something for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[26943] = { id = 26943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Sweet Gnome", description = "I used t' have quite the home back in Ironforge. That is, I did until I was booted out to make way for the gnomes.\n\nThey couldn't stop a bunch of troggs with all them gizmos and machines! An' I have to pay for their weakness?\n\nNo, sir. No longer.\n\nGo to Gnomeregan and talk to Commando Murd Doc. Sure, he's a gnome, but his crew, S.A.F.E. I think they call 'em, are going to take Gnomeregan back.\n\nGo! I want my house back!", sourceObjective = "Speak to Murd Doc.", completion = "Never thought I'd see a {race} like you down here. Any particular reason you're risking life and limb?", sourceObjectiveStatus = "unverified-source-field" }
quests[26944] = { id = 26944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploring Gnomeregan", description = "The gnomish capital, Gnomeregan, hasn't been under their control for some time now. I know what it feels like to lose a home.\n\nPlease, venture inside Gnomeregan and speak to Commando Murd Doc, a member of S.A.F.E. If there's anything at all that you can do to help them take their home, I urge you to do so. There are dark secrets in those halls.", sourceObjective = "Speak to Murd Doc.", completion = "Never thought I'd see a {race} like you down here. Any particular reason you're risking life and limb?", sourceObjectiveStatus = "unverified-source-field" }
quests[26945] = { id = 26945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning New Techniques", description = "There's no better time to get the upper hand in battle than at the start. Let me teach you a technique for charging into battle and stunning your opponent.\n\nI want you try it. Look for a training dummy near the southeastern edge of Aldrassil.", sourceObjective = "Learn Charge from Alyissia. Look for a Training Dummy near, and practice using Charge.", progress = "Speed and momentum are important tools for beating your opponents. Have you been practicing your charge?", completion = "You've proven a capable student. When it is time to resume your training, return to me and I will show you other techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26946] = { id = 26946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rogue's Advantage", description = "I'm certain that by now, you've mastered using Sinister Strike against your enemies, but I want to show you a technique you can use to follow a successful series of Sinister Strikes. It's called Eviscerate and it can be a strong way to end a combination of attacks.\n\nI want you try it. Look for a training dummy near the southeastern edge of Aldrassil.", sourceObjective = "Learn Eviscerate from Frahun Shadewhisper. Look for a Training Dummy southeast of Aldrassil and practice using Eviscerate 3 times.", progress = "With our ability to build highly effective and devastating combinations of attacks, we rogues are formidable opponents.", completion = "You've learned quickly. If you are as sharp as you seem to be, you may prove to be one of my best students yet. Return to me when you are in need of further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26947] = { id = 26947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Woodsman's Training", description = "When most people think of the kaldorei, they conjure visions of druids and sentinels, but the way of the hunter is just as ancient and just as venerable.\n\nI've been observing you, and you've had quite a bit of experience handling that bow. I want to show you a shooting technique that I often use in combat.\n\nI want you try it. Look for a training dummy near the southeastern edge of Aldrassil.", sourceObjective = "Learn Steady Shot from Ayanna Everstride. Look for a Training Dummy southeast of Aldrassil, and practice using Steady Shot 5 times.", progress = "This is a basic technique, but it will serve you well for many years to come.", completion = "You are a quick study in our ways. I look forward to continuing your training in the future. Return to me when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[26948] = { id = 26948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejuvenating Touch", description = "Druids play an important role in our society, but all too often we are seen as passive dreamers in a world that is changing around us. I want to teach you a basic healing technique and with it, I want you to go out in the world and aid the ailing and the fallen.\n\nUse your new knowledge to heal the wounds of sentinels who have been injured defending Shadowglen.", sourceObjective = "Learn Rejuvenation from Mardant Strongoak. Use Rejuvenation to treat a Wounded Sentinel in Aldrassil.", completion = "You have mastered the basics of the healing ways quickly, {name}. I have no doubt that your healing skills will often come in handy. Return to me when you need further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26949] = { id = 26949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing for the Wounded", description = "As a priest, you will often be called upon to heal the wounds of injured comrades. I want to teach you a basic healing technique and with it, you will be able to ease the suffering of the wounded and hasten their recovery.\n\nUse your new knowledge to heal the injured sentinels recovering within Aldrassil.", sourceObjective = "Learn Flash Heal from Shanda. Use Flash Heal 5 times to treat the Wounded Sentinels in Aldrassil.", completion = "You will find no lack of allies in need of healing. Return to me when you need further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26950] = { id = 26950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Side of the Light", description = "The Scarlet Crusade lures in anxious young warriors with their promise to eradicate the undead. What they don't see is the dark underbelly of the entire operation.\n\nInterrogator Vishas is the cruelest man I've ever had the displeasure to meet - he 'extracted' information from my mother during the initial outbreak of the plague. The merciless Bloodmage Thalnos watches over their graveyard.\n\nThe crusaders' zealous holy rage blinds them from their own darkness. Make them regret their hypocrisy.", sourceObjective = "Kill Interrogator Vishas and Bloodmage Thalnos.", completion = "What do you mean Thalnos was an undead? That's impossible. This is a holy place, the Scarlet Crusade would never allow...\n\nTake this as a reward, and get some rest. The crypts must have gotten the best of your nerves.", sourceObjectiveStatus = "unverified-source-field" }
quests[26951] = { id = 26951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleanup on Isle E.", description = "The Battle to reclaim the Echo Isles was a costly one.  But well worth it, {class}.  The great spirit, Bwonsamdi, helped our warriors defeat the foul Zalazane.  He protected our warriors with spirits from the island.  But some of those spirits fell in battle.  Help put those spirits to rest.  On the Echo Isles, you will find masks laying about gather them and bring them here.You will be able to choose one of these rewards:", sourceObjective = "Gather 8 Disenchanted Tiki Masks.", sourceObjectiveStatus = "unverified-source-field" }
quests[26952] = { id = 26952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "I don't like the looks of what the Forsaken are doing here at the Bulwark.  Bombs, cauldrons, needless bloodshed... none of these embody that which the Argent Crusade stands for.  Furthermore, I don't like the fact that they employ mercenaries like yourself.\n\nNothing against you personally, {class}.  It's just that you could be doing so much more for yourself.  If you're interested in healing the plaguelands, rather than re-plaguing them, then report to Field Agent Kaartish at the Menders' Stead to the east.", sourceObjective = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", completion = "Welcome, {class}.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[26953] = { id = 26953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki, the Druid", description = "I am Adrine Towhide, a druid of the Cenarion Circle.  You can thank us for healing this land, where once there was only death.\n\nWe accept all who choose to follow the druidic path, regardless of race, faction, or talent.  Occasionally that means we enlist a druid who needs more help than others.\n\nI'd like you to meet Zen'Kiki.  He's pretty new, and he's still learning his craft.  Would you mind taking him out with you for a while?  You can practice combat on the plagued animals that roam nearby.", sourceObjective = "Kill 20 plagued wildlife with Zen'Kiki by your side. You may kill Hulking Plaguebears, Diseased Wolves, Venom Mist Lurkers, or Plague Lurkers.\n\nReturn to the Menders' Stead if you become separated from Zen'Kiki.", completion = "It looks like Zen'Kiki is still having a little bit of trouble with his shapeshifting.", sourceObjectiveStatus = "unverified-source-field" }
quests[26954] = { id = 26954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Approach", description = "Among other things, Zen'Kiki needs to work on his spell accuracy.  I could see his wrath spells spiraling out of control even from here!  In fact, I used them as a marker to follow your progress through the woods.\n\nPerhaps we can use Zen'Kiki another way.  Take him up to the top of the hill just to our east.  The diseased hawks that circle above that hill must be destroyed.  Ask Zen'Kiki to shoot at these hawks.  Even if he can't hit them, he will distract them so you can finish them off.", sourceObjective = "Bring Zen'Kiki to the top of the hill east of the Menders' Stead, then use him to summon and kill 7 Diseased Hawks.", progress = "Back so soon?", completion = "Now we're getting somewhere.  How many birds did Zen'Kiki end up killing?\n\nNone?  You killed them all yourself?\n\nAlright, I suppose we'll have to find another use for him then.  I will let you know when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[26955] = { id = 26955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki and the Cultists", description = "While you've been away, I've been trying a different approach on our friend Zen'Kiki.  I believe he may have a future as a healer.  This is mainly because healing spells never miss.\n\nI hear from Field Agent Kaartish that the cultist camp to the east is where the plagued animals are coming from.  I hope you don't mind escorting Zen'Kiki over there... perhaps he can help heal some of the plagued animals within the camp.", sourceObjective = "Bring Zen'Kiki to the Malicia Outpost in Western Plaguelands, then break 4 Captive Plaguebears out of their cages and allow Zen'Kiki to heal them.", completion = "By the grace of the Earthmother, he's done it!  Thank you, {name}!\n\nI admit, I had nearly given up hope on Zen'Kiki.  It is only due to your patience and diligence that he has come into his own as a druid and member of the Cenarion Circle.  And that's without even mentioning the good you've done for nature.\n\nYou have my admiration and respect.", sourceObjectiveStatus = "unverified-source-field" }
quests[26956] = { id = 26956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Ain't Sayin' You a Gourd-Digger...", description = "{race}!  I'm glad someone's here to help me out.\n\nWe Cenarion druids have re-cultivated Dalson's Farm, immediately behind me.  The land has flourished and our crops have been successful... mostly.\n\nA few plants seem to still be infected by the plague that ran through this land.  Perhaps their roots were too deep, perhaps the seeds were weak... I cannot say.  All I can say is that I need an able {class} like you to help me remove the bad plants from the good ones.", sourceObjective = "Remove 6 Bad Corn, 4 Rotten Apples, and 3 Unhealthy-Looking Pumpkins from Dalson's Farm in Western Plaguelands.", progress = "Have you finished killing... er, removing those plants yet?", completion = "Thank you for your help, {name}.  I know that picking vegetables isn't the most heroic task imaginable, but even the humblest tasks have their rewards.", sourceObjectiveStatus = "unverified-source-field" }
quests[26957] = { id = 26957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Long Trip Home", description = "I've been many places in my life, good {class}.  I fought the battle for Ahn'Qiraj, passed through the Dark Portal into Outland, and joined the Argent Crusade to beat down Scourge in coldest Northrend.\n\nBut before it all, I was a farmer here in Lordaeron.  Now I find myself here in Hearthglen, a scant few miles from home.  It's time I paid my respects.\n\nI'm headed to the Menders' Stead before I return home.  I wouldn't mind meeting up with you again once I get there.", sourceObjective = "Reconvene with Del Gahrron at the Menders' Stead in Western Plaguelands.", completion = "It would appear that I arrived before you, {name}.\n\nField Agent Kaartish gave me the details about my old home.  It seems my battles with the Scourge aren't quite over yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26958] = { id = 26958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Lesson", description = "Let's start your training right away. I want to teach you a combat technique that you'll find useful at the start of battle. By charging your opponent before the fight begins, you can stun the enemy and momentum will be on your side.\n\nI want you to try out this technique using the training dummies to the northwest of the Crash Site. Return to me when you think you've mastered it.", sourceObjective = "Learn Charge from Kore. Find a Training Dummy on the northwest side of the Crash Site and practice using Charge.", completion = "Keep that technique handy, {name}. I find myself using it all the time. Return when you're ready for further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26959] = { id = 26959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stripping Their Defenses", description = "We need to eliminate the Scarlet Monastery's defenses before a true invasion can begin. Venture deep into here, their library, and assassinate Houndmaster Loksey and Arcanist Doan. They maintain the powerful defenses that protect their comrades.\n\nMy own magic will ensure your actions go undetected by the rest of the monastery. Once they are dead, I can summon in additional reinforcements to aid in our attack.\n\nWe must be successful, {name}, the Dark Lady will not tolerate failure in the slightest.", sourceObjective = "Eliminate Houndmaster Loksey and Arcanist Doan.", progress = "Did you take care of Loksey and Doan? Failing me is failing the Dark Lady, {race}.", completion = "I knew I could count on you! These fools will never know what hit them.", sourceObjectiveStatus = "unverified-source-field" }
quests[26960] = { id = 26960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Son, the Prince", description = "Great burdens have been placed on my son's shoulders in his short lifetime, and I fear his responsibilities are only going to grow.\n\nHe will never learn leadership confined to the keep, but I am loath to send him forth without escort.\n\n{name}, your deeds in the wake of this cataclysm are already legendary. You would be an excellent mentor for young Prince Anduin.\n\nPlease, introduce yourself to him. There is some pressing city business that you both can attend to for me.", sourceObjective = "Introduce yourself to Prince Anduin in Stormwind Keep. Speak with King Wrynn once you are both acquainted.", progress = "How are you two getting along? Anduin is a quick study; show him the ways of a master {class}!\n\nAre the two of you ready?", completion = "Excellent, Anduin will learn a lot by shadowing you.\n\nRemember, stay within the city's borders. Keep him out of trouble. And above all else, guard him with your life.\n\n<King Wrynn turns his attention to his son.>\n\nAnduin, no adventures! Stay close to {name} and return to the keep should you see any trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[26961] = { id = 26961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Idols", description = "Recently, just before the troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the troggs chased us away from the ruins! And those idols have a strange effect on the troggs. It makes them go berserk!\n\nBring me 8 idols - I want to study them, and I want them out of trogg hands!  You can find the idols on the troggs infesting the site.", sourceObjective = "Bring 8 Carved Stone Idols to Magmar Fellhew at Ironband's Excavation.", progress = "Do you have those idols?  We must study them and report our findings to Ironforge!", completion = "You got them!  Nicely done, {name}!\n\nAnd you don't look too worse for wear, even with those berserk troggs about.  I'm going to keep my eye on you...you show some promise.", sourceObjectiveStatus = "unverified-source-field" }
quests[26962] = { id = 26962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stripping Their Offense", description = "As you can see, {name}, our first assault on the Armory did not go as planned. We had taken the nearby courtyard until the Scarlet Champion, Herod, showed up.\n\nWe must continue our assault. The Scarlet Crusade will never be allowed to train another warrior here, let alone launch an attack on the Undercity.\n\nYour task should be obvious. Down the Scarlet Champion.", sourceObjective = "Kill Herod.", completion = "Herod is slain! The Armory will fall!", sourceObjectiveStatus = "unverified-source-field" }
quests[26963] = { id = 26963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steadying Your Shot", description = "Let's start your training right away. It's going to be a struggle to survive here, and you'll play an important role in making sure our people are safe and well-supplied. I want to show you a shooting technique that I use all the time.\n\nTry out this technique using the training dummies to the northwest of the Crash Site. Return to me when you think you've mastered it.", sourceObjective = "Learn Steady Shot from Keilnei. Find a Training Dummy on the northwest side of the Crash Site and practice using Steady Shot 5 times.", completion = "Keep that technique handy, {name}. I find myself using it all the time. Return when you're ready for further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26964] = { id = 26964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Silverpine Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.\n\nNow, more than ever, your help is needed in routing the enemy infestation of the region and conquering the port of Gilneas!\n\nTo reach Forsaken High Command you must travel south through Tirisfal Glades and enter Silverpine Forest. From there, follow the road south until you reach Forsaken High Command.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.", completion = "Most excellent! A new recruit has arrived. There is much to do... much to do I say.", sourceObjectiveStatus = "unverified-source-field" }
quests[26965] = { id = 26965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Cometh", description = "You're just in time, {name}nub. It is {name}nub, right?\n\n<Grand Executor Mortuus looks at a sheet of paper.>\n\nYes, that's what the paperwork says: \"{name}nub.\"\n\n<Grand Executor Mortuus points to your name on the sheet of paper.>\n\nWhere was I? Oh yes, you're just in time! The Warchief should be arriving at any moment to meet with our leader and savior, the Dark Lady herself. Just stand by and be at your best behavior. I expect that when this demonstration is over we will all receive commendations!", sourceObjective = "Stand by for Warchief Garrosh Hellscream's arrival.", progress = "Stand at attention, Grumphacknub!", completion = "Well that was unexpected. I am not one to doubt our Warchief, but...\n\nNevermind! We have work to do. I'm sure the Dark Lady and the Warchief will get this all worked out.", sourceObjectiveStatus = "unverified-source-field" }
quests[26966] = { id = 26966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Power", description = "As a paladin, you're no stranger to the Light that touches all of us. But you also have the unique power to call upon the Light to help you in battle.\n\nWhile under the effects of the Seal of Righteousness, each melee attack will deal extra holy damage. From time to time, you can also use Judgement to unleash your seal's power for another attack.\n\nI want you to try out these techniques using the training dummies to the northwest of the Crash Site.", sourceObjective = "Learn Seal of Righteousness and Judgement from Aurelon. Apply Seal of Righteousness, find a Training Dummy on the northwest side of the Crash Site and use Judgement.", completion = "You've proven yourself a quick learner, {name}. I look forward to training you again when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[26967] = { id = 26967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for the Scarlet Monastery", description = "Behold the might of the Forsaken! The unstoppable will of the Dark Lady flows through our bodies! \n\nThe vast majority of the crusade's remaining forces have fled. Some, however, remain defiant.\n\nYou have been instrumental in this campaign's success. Sylvanas extends the honor of slaying her last remaining enemies to you, {name}.\n\nShow no mercy.", sourceObjective = "Kill Scarlet Commander Mograine and High Inquisitor Whitemane.", progress = "Have you performed the Dark Lady's will?", completion = "Yes! The Scarlet Monastery now belongs to the Forsaken! None can escape our wrath!\n\nYou've completed your task with the precision of a true champion. Take this as a reward, courtesy of the Banshee Queen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26968] = { id = 26968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Missiles", description = "In your future as a mage, you'll be expected to master a wide variety of spells. In fact, I want to teach you one right now. It's called Arcane Missiles and it allows you to throw volleys of arcane energy at your opponent. However, you won't be able to use it all the time. Each time you cast a spell, there's a chance you'll trigger an opportunity to use the missiles.\n\nI want you to try out this technique using the training dummies to the northwest of the Crash Site.", sourceObjective = "Learn Arcane Missiles from Valaatu. Find a Training Dummy on the northwest side of the Crash Site and practice using Arcane Missiles 2 times.", progress = "Have you practiced your charge?", completion = "You've mastered the use of this new spell quickly, {name}. I only wish all of my students were as talented. Return to me when you find yourself in need of further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26969] = { id = 26969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "Your walk with the elemental powers will take you to many places. Let us start your journey with a simple, but useful, lesson. I want to teach you to a basic combat technique.\n\nOnce you have completed training, go practice your new skill using the training dummies to the northwest of the Crash Site. Return to me when you are finished.", sourceObjective = "Learn Primal Strike from Firmanvaar. Find a Training Dummy on the northwest side of the Crash Site and practice using Primal Strike 3 times.", completion = "It is a pleasure to teach such a capable student. As long as you continue the traditons faithfully, the shamanic arts will never be lost to our people again. Return to me when you need further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26970] = { id = 26970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Injured", description = "As a priest, one of your most important duties is to use the Light's power to aid the wounded. There are no lack of people here who could use your skills, {name}. Allow me to show you a quick, simple heal that you can use to treat any ally.\n\nUse your newfound knowledge to help me treat those wounded in the crash.", sourceObjective = "Learn Flash Heal from Zalduun. Use Flash Heal 5 times to heal the wounds of Injured Draenei at the Crash Site.", progress = "Have you seen to the wounds of the crash survivors?", completion = "You'll often find your skills as a healer in demand, {name}. Do not hesitate to return when you need more training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26971] = { id = 26971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "A noise in the main chamber of the temple draws your attention. You hear a familiar laugh... Lorthuna. She's returned to interrupt the ritual - you must stop her!", sourceObjective = "Kill High Priestess Lorthuna.", progress = "Stop Lorthuna! Don't let her interrupt the ritual!", completion = "Maruut said when all dis started dat he would gladly give his life ta see our task done. He would be proud of dis success... of dis death.\n\nDa rift be closed on dis side. Deepholm should calm down a bit. It'll be takin' time for Thrall to mend da wound in Azeroth, and we'll be needin' to remain until he finishes.\n\nThank you for all ya've done. I don't tink we could have been accomplishin' dis so soon without you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26972] = { id = 26972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Side of the Light", description = "I joined the Scarlet Crusade as a young paladin, eager to cleanse the world of evil. Little did I know of the dark truth to these fanatics.\n\nInterrogator Vishas and Bloodmage Thalnos oversee this graveyard. They take great pleasure in torturing new recruits endlessly to ensure that they are 'pure'. It is an affront to the light, {class}!\n\nNo longer can I be a part of this corrupt organization. You're going to have to kill them both, so that others will never endure the same pain I did.", sourceObjective = "Kill Interrogator Vishas and Bloodmage Thalnos.", progress = "I cannot help you with your task - if we are to cleanse this place then I must maintain my cover.", completion = "What do you mean Thalnos was an undead? That's impossible. The entire mission of the Scarlet Crusade is to destroy the undead! There's just no way...\n\nYou have muddied my thoughts. Please take this reward for your achievement and leave me to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26973] = { id = 26973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only True Path", description = "I think that the root of the crusade's corruption can be found here. Arcanist Doan watches over the library, and teaches many young recruits to wield the arcane arts.\n\nThe Light is the only true path! You must kill him, {class}, and redeem this glorious movement!\n\n<Joseph the Awakened shifts nervously.>\n\nYou'll want to dispose of Loksey as well. His hounds seem to disapprove of our noble intent.", sourceObjective = "Eliminate Houndmaster Loksey and Arcanist Doan.", completion = "Good work! I just know the Light shines favorably upon us for our work. Our cause is righteous!", sourceObjectiveStatus = "unverified-source-field" }
quests[26974] = { id = 26974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The False Champion", description = "We...we...we had to kill them! They were coming right for us!\n\nYou believe me, don't you {name}?\n\nHerod is not the true champion of the Scarlet Crusade. I am! He took what was rightfully mine!\n\nYou should kill him. He's...a menace! Trains the soldiers to kill anyone instead of just the undead!\n\nI'll reward you handsomely...", sourceObjective = "Kill Herod.", completion = "So he's really dead? That means...I, Joseph, am the new Scarlet Champion!!!\n\nTake this. I don't have a need for such possessions anyways! I'm the Scarlet Champion, after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[26975] = { id = 26975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying the Fleet", description = "I am amassing a warfleet to assault Twilight Highlands and bring an end to Deathwing's lackeys. My soldiers are ready but fleet preparations lag behind.\n\nMy men at the docks need some inspiration and motivation. A visit from the Prince here should lift their spirits and remind them of the bright future they're fighting for.\n\nTake Prince Anduin to the docks with you and speak with Supply Sergeant Graves. I want Anduin to observe how a natural leader handles the situation.", sourceObjective = "Escort Prince Anduin to the Stormwind Docks and talk to Supply Sergeant Graves. If you get separated from the Prince, you'll find him in the Stormwind throne room.", progress = "I was told to expect the Prince Regent. Who are you?", completion = "<Graves bows respectfully to the Prince.>\n\nPlease understand your highness, the men are working double-shifts. The scale of your father's operation is enormous.\n\nBut we will endeavor to wrap things up. I give you my word.", sourceObjectiveStatus = "unverified-source-field" }
quests[26976] = { id = 26976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for the Scarlet Monastery", description = "Oh, it's great to see you again {name}! I'm afraid I'm going to need your help.\n\nYou see, Mograine's the Commander here along with High Inquisitor Whitemane, and they tried telling me that I wasn't really the new Scarlet Champion! 'Course, the boys and I didn't take kindly to that.\n\nWe're taking the Scarlet Monastery for our own and re-establishing the order as it always should have been - with me at the head of things! I'll take care of the Forsaken and the Scourge for good.\n\nHelp an old friend out?", sourceObjective = "Kill Scarlet Commander Mograine and High Inquisitor Whitemane.", completion = "Yes! The Scarlet Monastery is ours! You're a real friend. Take this as a reward, and feel free to visit again once I've taken the Undercity too.\n\nIt'll be a Scarlet Paradise!", sourceObjectiveStatus = "unverified-source-field" }
quests[26977] = { id = 26977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Investigation", description = "The city is still reeling from the seditious acts of the Twilight's Hammer in recent months. They prey on peasant fears and corrupt our most important citizens. We need to find out how deep the conspiracy runs.\n\nI've tasked Major Samuelson of the Stormwind City Guard to head up an investigation. He's right here in the throne room. See if you can assist his efforts.", sourceObjective = "Speak with Major Samuelson in Stormwind Keep.", completion = "Hmmm, yes? My investigation of the Twilight's Hammer. Of course.\n\nYour assistance will be valuable.", sourceObjectiveStatus = "unverified-source-field" }
quests[26978] = { id = 26978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Needs Cauldrons?", description = "Have you seen the condition of Felstone Field?  The Alliance forces at Andorhal have taken the area, and they're using it to... to... to grow CROPS!\n\nI almost liked it better when the Scourge held the area.  At least they had the sense to put a giant plague cauldron in the middle of the field.\n\nWe're going to take that farm back from these humans, {name}.  Take these drums and place them at key locations around the field.  I'll be waiting here at the Bulwark.", sourceObjective = "Place Dithers' Plague Drums near the Windmill, the Grain Silos, the Ranch House, and the Barn at Felstone Field.", completion = "<Dithers practically glimmers with excitement.>\n\nThe drums are placed?  In their positions?\n\nVery well then, I will give the word to the High Executor.  When the time is ready, he will be the one to press the ignition switch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26979] = { id = 26979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange New Faces", description = "Now that Felstone is ours, we can use its acreage - and any dead bodies we find - for our own purposes.  I've received orders from higher up that you are going to be helping out in this process.\n\nYou may have met Lindsay Ravensun on the battlefield in Andorhal.  I've never met her before, but she seems to have made some friends in high places, because she's taking over operations at Felstone.  You're to meet her at the charred Scarlet camp... the one you scouted out earlier.", sourceObjective = "Report to Lindsay Ravensun at the Charred Outpost in Western Plaguelands.", completion = "{name}.  The Dark Lady watches over you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26980] = { id = 26980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swiftgear Station", description = "You've done good work here, {name}. Askin' you to haul sandbags would be a waste, to be honest; I'd rather send you along where your skills are needed.\n\nWe've got a small outpost up north in the marsh. Swiftgear's the gnome that built it, but you'll want to talk to Shilah Slabchisel and help her with Ironforge matters.\n\nI'll admit, she's a looker... but I wouldn't make the mistake of getting fresh with her! They don't call their family Slabchisel for nothing.", sourceObjective = "Speak with Shilah Slabchisel at Swiftgear Station, north of Menethil Harbor.", completion = "Stoutfist sent you, eh? He's a good captain, runs his men well. Just wish he'd stop starin' at my midriff.\n\nDon't let me catch you doin' it either. We've work to take care of here!", sourceObjectiveStatus = "unverified-source-field" }
quests[26981] = { id = 26981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whelgar's Retreat", description = "Prospector Whelgar's been leading an excavation in the mountains southeast of here for quite some time. He had some raptor problems back in the day, but things were going better recently.\n\nJust the other day, we got word he had to evacuate the entire digsite again. I'm not sure what's going on there, but I can't imagine the cataclysm making a quarry any safer than it was before.\n\nThere's good dwarves working there, {name}. Would you go see what's wrong there, and maybe lend a hand?", sourceObjective = "Speak with Prospector Whelgar at Whelgar's Retreat, southeast of Swiftgear Station.", completion = "Well met, {class}. We've got raptor problems for sure... sort of.\n\nMore like the entire dig site deciding to attack us. I've never seen rocks and fossils get so upset!", sourceObjectiveStatus = "unverified-source-field" }
quests[26982] = { id = 26982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Monastery", description = "The same Monastery in Tirisfal Glades that the Scarlet Crusaders now occupy used to be a major training ground for our paladins. Now the Forsaken loom over it from the Undercity and the Crusade prevents us from utilizing it to train the very soldiers we need to deal with the Forsaken!\n\nLook, I don't trust him, but Joseph the Awakened waits inside the graveyard. Go speak with him - although he is a crusader, he says he now rebels against them, providing us with an opportunity to take back what's ours.", sourceObjective = "Visit Joseph the Awakened.", completion = "Captain Nials sent you? I haven't seen her in ages! How is she? Did she get my letter?\n\nOh, you're not here for that. Well then, let's get down to business!", sourceObjectiveStatus = "unverified-source-field" }
quests[26983] = { id = 26983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Close Enough", description = "Make no mistake - there is a ton of stuff to be done here! However, we also need to strike at the Forsaken where it hurts. The Scarlet Monastery in Tirisfal Glades is the perfect distance from the Undercity and Brill.\n\nReport to Joseph the Awakened in their Library. He's a rebel crusader that can hopefully help us take the Monastery as our base of operations in that region, and maybe take out Arcanist Doan, one of their most powerful mages, in the process.", sourceObjective = "Visit Joseph the Awakened.", completion = "You came here from Southshore, eh? I bet you hunger for revenge against the vile Forsaken that trashed the place. The Scarlet Crusade can help take care of that!\n\nRight after you help me realign their misguided souls, that is.", sourceObjectiveStatus = "unverified-source-field" }
quests[26984] = { id = 26984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old, Crazed Friend", description = "Joseph the Crazed was one of my good friends before he joined the Scarlet Crusade up in the Scarlet Monastery in Tirisfal Glades. I heard that he's in the Armory there trying some ridiculous attempt at taking over Herod's position as Scarlet Champion.\n\nIt's a death wish to challenge Herod like that! Go up there and try to talk him out of it.", sourceObjective = "Visit Joseph the Crazed.", completion = "You look pretty tough, {class}. There are wrongs to be righted here. Let's get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[26985] = { id = 26985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pitting Madness Against Madness", description = "Our renewed forces can handle the situation here for a while without you. I've received reports that Joseph the Insane, a former Scarlet Crusade officer, is in the Scarlet Monastery Cathedral and is taking his band of renegades to strike out against Scarlet Commander Mograine.\n\nThis is an excellent opportunity. Go there and help him with his insane task, and maybe we can use the Monastery as an excellent stronghold right at Sylvanas' doorstep!", sourceObjective = "Visit Joseph the Insane.", completion = "Wait, you were sent here by THE Shandris Feathermoon? I can barely believe my ears! To know that my cause is supported by her massive army...\n\nYes, yes, you will be perfect. You're the key to my future!", sourceObjectiveStatus = "unverified-source-field" }
quests[26986] = { id = 26986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Scarlet Monastery", description = "Oftentimes the best way to ensure our men sustain as few injuries as possible is to cause great harm to our enemies in their very homes and prevent battles from ever occurring!\n\nTravel to the Scarlet Monastery and speak with Dark Ranger Velonara in their graveyard. She is leading a Forsaken assault there and could benefit from a seasoned {class} such as yourself.", sourceObjective = "Report to Dark Ranger Velonara.", completion = "It looks like Darthalia sent an able {class}, as I requested.", sourceObjectiveStatus = "unverified-source-field" }
quests[26987] = { id = 26987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Way", description = "My people are not generally fond of the arcane arts that so many other races abuse. Thankfully the wizards within the Scarlet Monastery library are separated from us by considerable land, but their ability to transcend the physical realm concerns me and, ultimately, my tribe's survival.\n\nTravel far to the west to the monastery's library and speak with Dark Ranger Velonara there. Her forces are already poised to strike at Arcanist Doan himself, head magi for the crusade.", sourceObjective = "Speak to Dark Ranger Velonara.", completion = "I'm surprised to see Huntsman Markhor working with me for once. He's usually quite stubborn. He does tend to a strong hatred for magic, though.\n\nI hope you do, too, {class}, because we're going to strip the Scarlet Crusade of theirs.", sourceObjectiveStatus = "unverified-source-field" }
quests[26988] = { id = 26988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving Things Along", description = "I'm waitin' on some very powerful reagents I ordered from the Undercity not long ago. I heard that the shipment is late because the Scarlet Monastery's crusaders are blocking its passage. Da Scarlet Champion, Herod, is likely to blame for dis annoyance.\n\nPlease go speak to Dark Ranger Velonara in the Scarlet Monastery's armory, she is goin' to 'take care' of Herod, which means my shipment will arrive safely!", sourceObjective = "Visit Dark Ranger Velonara.", completion = "Yayo'jin is correct, you helping me here will aid her in the Hinterlands as well.\n\nAll the more reason to get started immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[26989] = { id = 26989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gilneas Liberation Front", description = "The battle over this region still rages, {name}nub. Although we soundly beat back the Gilnean defenses and took Gilneas for the Horde, a small group of rebels managed to escape. The \"Gilneas Liberation Front\" - as they call themselves - make attacks of opportunity against our forces in the field. The rebels have had a few minor victories and now grow brazen in their assaults! The time to strike back is now, {name}nub.\n\nVenture south into the wilds of Silverpine and kill any rebel that you cross.", sourceObjective = "Kill 10 Worgen Renegades.", progress = "What have you to report, Æthelwolfnub?", completion = "Peterbonenub has returned! And in one piece!\n\nDefender of Silverpine! Redeemer of the Horde! Peterbonenub, your bravery must be rewarded!", sourceObjectiveStatus = "unverified-source-field" }
quests[26990] = { id = 26990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water They Up To?", description = "It appears that the Sandfury trolls are working with the Twilight's Hammer.\n\nNo matter. That foul witch won't be sending her monster to MY city.\n\nCome, brave ones! We'll slick the sand with their gore and return home triumphant. Tell Hamuul Runetotem what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", sourceObjective = "Slay Kai'ju Gahz'rilla and inform Hamuul Runetotem in Thunder Bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[26991] = { id = 26991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Abroad", description = "Sometimes we must acknowledge the need to protect our allies so that they may protect us. This is one such occasion, {race}.\n\nTravel to the Scarlet Monastery near the Undercity in Tirisfal Glades. Once you arrive, go to the Cathedral and speak with Dark Ranger Velonara. She is leading the final assault against the crusade there, and it would benefit us all greatly to ensure our undead allies secure the monastery before the crusaders have a chance to attack their capital.", sourceObjective = "Find Dark Ranger Velonara.", completion = "Nazeer is a strong warrior - his hatred for our enemies rivals my own. You are welcome help to my forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[26992] = { id = 26992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agony Abounds", description = "You have no doubt heard about the incident that transpired at the Wrath Gate in Northrend, yes? Due to those unfortunate events we are strictly forbidden from using the strain of life-shattering blight that we finally perfected. Now we have rules and regulations and other nonsense!\n\nThey've given us some neutered version of the perfected blight and expect us to weaponize it.\n\nIf I'm to get this crap functional I'll need several bags full of ferocious doomweed. You'll find it all over Silverpine.", sourceObjective = "Gather 8 Ferocious Doomweed.", progress = "Have you collected the ferocious doomweed I requested?", completion = "Agony abounds, friend! The land itself threatens to devour us, and yet we persist. I wonder why that is? With this doomweed and the guts and gore that T'Veen needs, we might have something suitable to send to the Forsaken front.", sourceObjectiveStatus = "unverified-source-field" }
quests[26993] = { id = 26993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compendium of the Fallen", description = "Don't fret, I serve no master, {race}. Within these halls lies a book called the Compendium of the Fallen. It holds vast amounts of research that the Scarlet Crusade has done on my kind over the years.\n\nSimply put, I'd like you to retrieve it and bring it back to me. No questions asked.", sourceObjective = "Retrieve the Compendium of the Fallen.", progress = "I don't want to stay in a monastery packed full of undead-hating zealots for much longer. Surely you can understand why. Don't speak to me if you don't have the book with you.", completion = "Well done. How about I give you a nice reward for your work, and you don't tell a soul that you saw me here. Deal?", sourceObjectiveStatus = "unverified-source-field" }
quests[26994] = { id = 26994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Without Rhyme or Reason", description = "I heard that Joseph the Crazed wants you to kill Herod. While you're at it, how about you slaughter their top soldiers? I'll pay you well for your work.\n\nDon't worry about the why, just worry about the how.", sourceObjective = "Kill 3 Scarlet Myrmidons, 3 Scarlet Protectors, 3 Scarlet Guardsmen, and 3 Scarlet Evokers.", progress = "Let's not play games. Are they dead or not?", completion = "Very good. Yes, very good indeed.\n\nYour reward, as promised. No questions.", sourceObjectiveStatus = "unverified-source-field" }
quests[26995] = { id = 26995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guts and Gore", description = "If we're to get this new blight up and running we'll need clean beast guts. The problem is that clean beast guts are a rare commodity in Silverpine Forest. Most of the beasts here have succumbed to disease and thus only have diseased organs.\n\nDo a sweep of the forested area east of here for worgs and grizzled bears. Kill only the non-diseased variety and rip out their entrails. Bring me all of the clean guts that you can stuff into your backpack!", sourceObjective = "Recover 6 \"Clean\" Beast Guts.", progress = "Remember, I can only use clean beast guts for the new strain of blight we're developing.", completion = "Excellent! With these guts and the ferocious doomweed we'll be able to test out our new strain of blight. Now to select a suitable target...", sourceObjectiveStatus = "unverified-source-field" }
quests[26996] = { id = 26996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Under Their Noses", description = "In the right side-room of the accursed cathedral ahead there is a torch on the wall. Move it and a secret door will open. Inside is High Inquisitor Fairbanks. He is now an undead.\n\nI need him taken care of. Kill him in his own room if possible, I'd strongly prefer the crusaders not see him. You know the deal - kill him, and I'll reward you. No other words are necessary between us.", sourceObjective = "Kill High Inquisitor Fairbanks.", progress = "<Dominic stares at you.>", completion = "<Dominic hands you your reward. No words are spoken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26997] = { id = 26997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Usual Suspects", description = "<Samuelson scratches his chin, absently.>\n\nMy investigations reveal, ah, it's likely that there's trouble brewing among the Stormwind dock workers. Shifty lot. Don't trust 'em.\n\nYou should go there and shake the place down. Start grilling those longshoremen. That should keep you busy.\n\nGo rout out those Twilight infidels!", sourceObjective = "Grill 6 Stormwind Dock Workers in Stormwind Harbor.", progress = "Samuelson didn't seem to give you a lot of credit. Do you really think the dock workers have anything to do with the Twilight's Hammer?", completion = "This doesn't make any sense, {name}.\n\nWhy was Samuelson sending us out here on a wild goose chase?\n\nSomething doesn't feel right. We should poke around on our own...", sourceObjectiveStatus = "unverified-source-field" }
quests[26998] = { id = 26998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iterating Upon Success", description = "The concoction is finally ready, but before I can put my seal of approval on this strain, we'll need to run a field test.\n\nSpeak to Bat Handler Maggotbreath, here at High Command, and requisition a bat. The bat will take you to the Dawning Isles, east of here across Lordamere Lake, right into the heart of depravity itself - the Vile Fin murloc dens!\n\nUse the concoction against the murlocs and report the results back to me.\n\nThose results being that you killed them all, as commanded!", sourceObjective = "Kill 50 Vile Fin Murlocs.", progress = "Have you exterminated the Vile Fin murlocs of the Dawning Isles?", completion = "Potent enough to exterminate a thousand murlocs! I think I'll put that on the label. You've done well, {name}, and great work around here gets rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[26999] = { id = 26999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Era for the Plaguelands", description = "No longer does the Scourge hold this area.  We, the living, are retaking Lordaeron.\n\nWe have taken great strides already, as you have already seen.  The earth flowers, the trees grow tall and green, and the wildlife is beginning to return.  Yet a few remnants of undeath remain.\n\nWhile the trees and grass prosper, the animals are struggling.  Something is preventing them from healing, and I intend to find out what.  Bring me samples from the plagued wildlife so that I may study them more closely.", sourceObjective = "Obtain 4 Plague Lurker Samples, 4 Venom Mist Lurker Samples, 4 Hulking Plaguebear Samples, and 4 Diseased Wolf Samples.", progress = "Once the animals are healed, our duties here will be nearly complete.", completion = "This will be more than enough, {name}.  Now, I will need some time to perform my studies.", sourceObjectiveStatus = "unverified-source-field" }
quests[27000] = { id = 27000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Ropes", description = "Ah, it's good to be back in Northridge!  I've got my mill, my beautiful wife, a bouncing baby boy... I've even put in my hat with the Argent Crusade.  We'll be supplying Tirion's forces with lumber.\n\nMy lumberjacks were being exceptionally productive, too... up until the point when the spiders came.  Now they refuse to go any deeper in the woods.\n\nMaybe you can help me out.  Hop on one of my horses and use it to frighten those spiders.  Maybe we can avoid bloodshed and just scare them away.", sourceObjective = "Mount a Hearthglen Mustang at Northridge Lumber Mill, then use its Whinny ability to frighten 25 Northridge Spiders.", progress = "The spiders tend to be a little skittish.  One of the mustangs should be enough to scare them away.", completion = "Well, it sounds like they're certainly afraid of the mustang, but they're not leaving for good.  I can't have you running around on a horse forever.  Nor do I think you'd want to.\n\nFine.  Bloodshed it is.", sourceObjectiveStatus = "unverified-source-field" }
quests[27001] = { id = 27001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Means WAR (Wild Arachnid Roundup)", description = "The Highlord was generous enough to send some of his recruits to protect us here at the mill.  With your horsemanship skills, and their martial prowess, we can do away with this spider problem easily.\n\nHop back on that mustang and scare those spiders again, but this time, scare them all the way up here to the mill.  These Hearthglen recruits can handle things from there.", sourceObjective = "Mount a Hearthglen Mustang near the Northridge Lumber Mill, then use its Whinny ability to send 10 Northridge Spiders to the Hearthglen Recruits at the Northridge Lumber Mill. You can round up several spiders at once.", progress = "I don't need you to kill the spiders... that's what these soldiers are for.  Think of it as killing two birds with one stone: we're getting rid of the spiders, and the recruits are getting valuable combat experience.", completion = "That's much more like it!  Now my lumberjacks can get to work again.\n\nNice riding out there, {name}.  You cut a pretty impressive silhouette on that mustang.", sourceObjectiveStatus = "unverified-source-field" }
quests[27002] = { id = 27002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with the Highlord", description = "Oh, before you go, {name}... I have a message for you.  There's someone in Hearthglen who'd like to meet with you.  Said he's \"heard your name pop up\" a few times already.\n\nConsider yourself lucky, {name}.  Not everybody gets a personal audience with Highlord Tirion Fordring.\n\nOh, and feel free to use one of my mustangs for the ride up there.  They're the fastest money can buy.", sourceObjective = "Report to Highlord Tirion Fordring at Hearthglen in Western Plaguelands.", completion = "{name}.  It is truly a pleasure.\n\nI know you are young, and still training, but I've had my eye on you.  We among the Argent Crusade are always looking for promising new recruits, and you have indeed shown great promise.  I have no immediate tasks for you, but merely wished to meet you in person, and see for myself what type of {race} you really were.\n\nFor the time being, the amenities of Hearthglen are yours to enjoy.  I look forward to our next meeting, {name}.  You are dismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27003] = { id = 27003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Money", description = "Well, hello there!\n\nWhatever brought you, I'm so glad that you're here! My friends will never admit to it, but we could really use a hand.\n\nThe ancient region of Uldum has been exposed! Treasures beyond your wildest dreams, free for the taking!\n\nWe just need a bit of an escort, what with the bandits and all...\n\nYou'll accompany us, won't you?\n\nYou're welcome to all the loot you can haul off!", sourceObjective = "Accompany Adarrah's caravan into Uldum.", completion = "Smells like someone else was in this cell recently.\n\nGross!", sourceObjectiveStatus = "unverified-source-field" }
quests[27004] = { id = 27004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Plot", description = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest.\n\nOne of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, {name}.\n\nKeep searching the cultists until you find them.", sourceObjective = "Collect the Masters' Gate Plans.", progress = "Those plans are the key to everything.", completion = "<Mowi takes a look at the plans that you hand to her.>\n\nBut... but, this is just gibberish!\n\nWhat does this even say? What language is that?", sourceObjectiveStatus = "unverified-source-field" }
quests[27005] = { id = 27005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Plot", description = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest.\n\nOne of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, {name}.\n\nKill cultists at the Masters' Gate until you find them.", sourceObjective = "Collect the Masters' Gate Plans.", progress = "Those plans are the key to everything.", completion = "<The examiner takes a look at the plans that you hand to him.>\n\nThis is just gibberish!\n\nWhat does this even say? What language is that?", sourceObjectiveStatus = "unverified-source-field" }
quests[27006] = { id = 27006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fly Over", description = "I tried ta fly o'er the terrace an have a look fer myself, but those toastie eatin' pansies kept shootin' at me, an I couldn't get near.\n\nYa look like ya might be handy with the reins. Why don' ya take yer flyin' beastie up there ta the southwest and see what all the fuss is about?", sourceObjective = "Investigate the central area in the back of the Masters' Gate.", completion = "A waygate?! The culties dug up a Titan waygate?", sourceObjectiveStatus = "unverified-source-field" }
quests[27007] = { id = 27007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvermarsh Rendezvous", description = "Excellent work, {name}.  We know exactly where the meeting location is.\n\nThe Upper Silvermarsh is a mercury swamp to the east of here.  It's normally only inhabited by elementals and occasional stone troggs, but our scouts have seen some Twilight activity in the region.\n\nMake your way there and let's find a way to eavesdrop on the Forgemaster's meeting.", sourceObjective = "Go to the Upper Silvermarsh in Deepholm.", progress = "We'll get that fragment back, {name}.  We have no choice.", completion = "This is the place.  Our scouts confirmed the presence of high-ranking Twilight officers nearby as well as potential trogg hunting parties.\n\nBe on the lookout, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27008] = { id = 27008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fly Over", description = "I'm quite adept at riding my flying carpet. Unfortunately, when I tried to investigate what the cultists had uncovered up at the Masters' Gate, they nearly shot me down.\n\nYou look as if you might be skilled with the flying reins as well. Would you mind flying up there to the southwest to see what they've unearthed?", sourceObjective = "Investigate the central area in the back of the Masters' Gate.", completion = "A waygate?! They unearthed a Titan waygate.\n\nThis is very interesting and potentially very bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27009] = { id = 27009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coldbringer", description = "Amnennar the Coldbringer rules over the Razorfen Downs with very dark and powerful Scourge magic. I have managed to clear an opening in the thorns just above his seat of power, but his sorcery prevents me from launching an assault.\n\nIf you venture up the Spiral of Thorns and engage him, he will be distracted long enough for me to attack him briefly, weakening him before he can use his most deadly spells. Once he is weakened, destroy him without mercy.", sourceObjective = "Kill Amnennar the Coldbringer.", completion = "A job well done, {name}. The Quilboar here can no longer be saved, but at least they are no longer organized for attack, or slaves under Amnennar's tyrannic rule.\n\nLeave quickly, please. Razorfen Downs is without hope. It must be purged.", sourceObjectiveStatus = "unverified-source-field" }
quests[27010] = { id = 27010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quicksilver Submersion", description = "The troggs in Deepholm have proven to be every bit as hostile as the ones in Azeroth.  Yet perhaps their presence will prove useful to our efforts.\n\nThe crates they use for trawling through the mercury will conceal you perfectly if you submerge yourself beneath the marsh.\n\nUse it to approach the Twilight's Hammer camp in the eastern end of the Upper Silvermarsh undetected.", sourceObjective = "Obtain a Trogg Crate and use it to submerge yourself and eavesdrop on the Twilight's Hammer camp to the east.", completion = "We have the information we need.  Let's not tip our hand by engaging the enemy too soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[27011] = { id = 27011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redpine Thievery", description = "Farther to the south, you will find Redpine gnolls... a new arrival to the area.  You probably passed some on your way here.  Nathaniel pretends like they're not a problem, but I know better.\n\nI've seen them running away with our lumber at night.  I don't know what they'd do with lumber - they don't seem particularly handy - but that doesn't stop them from stealing it.  Head down to their camps and steal that lumber back.", sourceObjective = "Retrieve 10 piles of Northridge Lumber from the Redpine Camp in Western Plaguelands.", progress = "Some of the older lumberjacks tell me that the Redpine lived in the area several years ago, but left when the plague arrived.  That doesn't make it OK for them to steal, though.", completion = "I'll just put this back over in the lumber stores outside.  Nathaniel probably won't even notice it was missing.", sourceObjectiveStatus = "unverified-source-field" }
quests[27012] = { id = 27012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gnoll's Resolve", description = "I have my doubts about those gnolls' intentions.  They haven't attacked us yet, but their numbers are growing, and they seem to always have their weapons ready.  I'm no military expert, but that seems a little aggressive to me.\n\nMaybe if we took away some of their weapons, they'd be a little less likely to pose a threat to our mill.  I'd feel much better about the whole situation if you went down there and brought some of their weapons back to me.", sourceObjective = "Obtain 6 Redpine Staves and 6 Redpine Clubs from Redpine Gnolls.", progress = "I don't want to order some sort of mass gnoll genocide because of a mother's worries.  I'd just like to feel safe in my own home.", completion = "Thank you, {name}.  I'll be throwing these in the fire.  We don't want those gnolls just sneaking in and stealing them back.", sourceObjectiveStatus = "unverified-source-field" }
quests[27013] = { id = 27013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Close for Comfort", description = "I'm happy for Nathaniel: he's spent so long trying to return to Northridge, and now with the Scarlet Crusade out of the way, he can finally move back home.  It's just... even for such a seemingly-idyllic setting, it's not really the best place to raise a family.\n\nFor example: along this valley's edge, you will find rabid foxes searching for innocent prey.  Every once in a while I catch a glimpse of one looking right at me.\n\nPlease, {class}, remove some of these foxes.  I don't feel safe with them near.", sourceObjective = "Kill 12 Rabid Foxes near Northridge Lumber Mill in Western Plaguelands.", completion = "I feel a bit more relieved, {name}.  Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27014] = { id = 27014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowed Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the priest trainer, Seer Ravenfeather. If this note is from the seer, I would go looking for her immediately.", sourceObjective = "Speak to Seer Ravenfeather in Camp Narache.", progress = "I am pleased to meet you, {name}.", completion = "You have arrived at last. During your training in Camp Narache, I will guide you in the ways of the {class}. You have much to learn and I look forward to counting you among my students.", sourceObjectiveStatus = "unverified-source-field" }
quests[27015] = { id = 27015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the paladin trainer, Sunwalker Helaku. If this note is from the sunwalker, I recommend going to see him immediately.", sourceObjective = "Speak to Sunwalker Helaku in Camp Narache.", progress = "I am pleased to meet you, {name}.", completion = "We have much to cover. In time, the ways of the sunwalkers will be as plain and natural to you as the shaman's conversations with the elements.", sourceObjectiveStatus = "unverified-source-field" }
quests[27016] = { id = 27016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Joy of Boar Hunting", description = "Try to contain your excitement, {name}, for you are in the presence of the greatest boar hunter in Azeroth!\n\nTheir cunning intellect, rapid speed, ferocious strength, and resilient hide... yes, boars are the quarry of only the most masterful of hunters. Amateurs need not apply!\n\nWhy, I bet you've never even hunted such an exotic beast. I'll bet silver any day that you can't match my record of ten boars killed. Try the ones on the eastern shore of the loch... but don't hurt yourself now, rookie!", sourceObjective = "Kill 10 Mudbelly Boars.", completion = "You've killed ten already? H...hah! While you were out, I've broken my previous record! To ten... hundred! Yes, ten hundred boars!\n\nA bet is a bet, I suppose... here's your consolation prize, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27017] = { id = 27017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories from a Lost Past", description = "It's funny the things you remember.  I spent 16 hours a day working the fields, and every seventh day I'd head into bustling Andorhal to sell what I'd grown.  It was a tough life, but we did alright.\n\nBut I barely remember any of that.  When I think back to those days, I think about Gloria's smile, or Andrea waving from the window whenever I'd look up from the plow.\n\nThe farm's just a bit to the east, but I'm not sure I'm ready to go back, {name}.  I'd just like to make sure I hold on to these memories.", sourceObjective = "Travel to the farm house in Gahrron's Withering and gather any mementos you can find.", progress = "I wouldn't expect you to indulge the whims of a nostalgic old man, {name}.  Still, if you find yourself in the area...", completion = "This... Gloria used to read from this prayer book every night!  How had I forgotten?  She was so devout, {name}.\n\n\n\nOh...\n\nThis painting... my daughter, Andrea... she loved to... to paint...", sourceObjectiveStatus = "unverified-source-field" }
quests[27019] = { id = 27019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge of the Downs", description = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.\n\nListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but somebody needs to do it and I seriously doubt other adventurers will wander into this desolate place.", sourceObjective = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", progress = "I'm not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.\n\nIf you're willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I'm... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.", completion = "Fantastic, I thought you looked to be the heroic type!  We've got our work cut out for us {name}, I'm not going to lie to you.  If we stay focused on the task at hand, we should be able to come out on top.", sourceObjectiveStatus = "unverified-source-field" }
quests[27020] = { id = 27020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Lesson", description = "The time has come for your first lesson in the ways of the warrior, {name}, and a fitting lesson it is. I will teach you a technique for gaining the upper hand at the start of battle.\n\nCharge into the fray, surprising your enemy, and stunning him. After we have completed our lesson, I want you to try it for yourself.", sourceObjective = "Learn Charge from Harutt Thunderhorn. Locate a Training Dummy in Camp Narache and practice using Charge.", progress = "Have you mastered the charge?", completion = "You have done well, {name}. Return to me when you are in need of further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27021] = { id = 27021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "It is time for your first lesson, {name}. You have a long way to go to master the ways of the hunter, but each new skill is a step on that path. Let me show you a useful shot.\n\nWhen our lesson is concluded, I want you to try it for yourself.", sourceObjective = "Learn Steady Shot from Lanka Farshot. Locate a Training Dummy in Camp Narache and practice using Steady Shot 5 times.", progress = "Have you mastered the charge?", completion = "You have done well, {name}. Return to me when you are in need of further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27022] = { id = 27022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguishing the Idol", description = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; they...they literally consume their abductees from the Barrens.  I can shut down the idol and render it useless, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.\n\nAre you with me, {race}? Can I count on you to help me end their atrocities?", sourceObjective = "Protect Belnistrasz.", completion = "Belnistrasz's sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz's voice speaks directly to you.\n\n\"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in your kind has been once more renewed.  Take this as a reward befitting of a hero.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[27023] = { id = 27023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way of the Sunwalkers", description = "It is always a pleasure to meet a fellow Sunwalker. We are not as numerous as some of the more ancient orders, but our ways are no less powerful and our members no less respected.\n\nAllow me to teach you one of our most basic techniques -- seals and judgments. Using Seal of Righteousness allows you do deal extra holy damage with each swing and you may periodically use Judgement to inflict additional damage to your opponent.\n\nTry it for yourself.", sourceObjective = "Learn Seal of Righteousness and Judgement from Sunwalker Helaku. Locate a Training Dummy in Camp Narache and practice using Judgement.", progress = "Have you mastered the use of your first seal and judgement?", completion = "You have made me proud, {name}. You will make a fine Sunwalker. Return when you desire further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27024] = { id = 27024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partners in Crime", description = "Although Amnennar is the primary threat here, he is far from the only. You need to slay his lieutenants as well if their hold on the Downs is to be released.\n\nGlutton guards the beginning of the Spiral of Thorns.\n\nMordesh stands atop The Bone Pile inciting the Scourge into a ravenous frenzy.\n\nTuten'kash resides underground. In order to bring him out, you must strike the gong in The Caller's Chamber three times.\n\nGood luck, brave hero.", sourceObjective = "Kill Glutton, Mordresh Fire Eye, and Tuten'kash.", completion = "Well done! Without their leaders, the Scourge will pose no significant threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27025] = { id = 27025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thistle While You Work", description = "It's stabthistle season! Stabthistle seeds are responsible for up to 89% of seed-related injuries among hunters.\n\nYou'll find Stabthistle seeds mostly in the lower woodland just north of the lodge. They're commonly found at the base of trees, and they will stab and hurt you.\n\nI'd advise you to avoid them, but I actually need someone to help remove them for the sake of safety! Bring me back Stabthistle seeds so we can make sure others don't get hurt.", sourceObjective = "Collect 6 Stabthistle Seeds.", progress = "Handle them safely, now!", completion = "I've been informed there's a bear warning active for the woodlands as well! They love those stabthistle seeds.\n\nIt's a good thing you gathered those so they don't attract more bears!", sourceObjectiveStatus = "unverified-source-field" }
quests[27026] = { id = 27026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defcon: Bobcat", description = "Stop everything! It's come to my attention that there's been bobcat sightings near the lodge. Bobcats!\n\nNow mind you, I've never seen a bobcat, but they're surely dangerous. They're like mountain lions or something. I don't want anyone leaving until the area is secure!\n\nAnyone but you, that is. I'll pay you to help secure the area, {class}. But don't get your face ripped off.", sourceObjective = "Kill 8 Bobcats.", completion = "Okay, yes, I have already been informed that bobcats are much smaller than I was assuming. But that's still pretty dangerous for gnomes!\n\nYou've done a good thing for the safety of this lodge, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27027] = { id = 27027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "I know you've been busy helping the braves protect Camp Narache from the bristlebacks. We're going to need all the hammers and all the luck we can get. Allow me to teach you a simple combat technique to help you in battle.\n\nPrimal Strike should help you fell your enemies faster. Try it out for yourself.", sourceObjective = "Learn Primal Strike from Meela Dawnstrider. Locate a Training Dummy in Camp Narache and practice using Primal Strike 3 times.", completion = "Well done, {name}. I see you will have no trouble mastering our more advanced arts as you gain experience. Return to me when you need further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27028] = { id = 27028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornet Hunting", description = "We're always looking for new game around here. Daryl may like his boars, but the rest of us prefer things more exotic.\n\nNow, I'd never say the Loch draining was a good thing, but it did have a silver lining. The swampy ground's brought in new prey: Hornets!\n\nGiant hornets, mind you. Not many hunters have tussled with massive bugs before. It's rather novel.\n\nIf you'd like to give it a try, I'll wager with you. Bring me back some of those nice glossy wings of theirs and I'll pay up.", sourceObjective = "Collect 6 Glassy Hornet Wings.", progress = "How go those wasps?", completion = "Lovely specimens you've got there! Here's my wager, lad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27029] = { id = 27029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cure the Scourge", description = "Far more effective than killing swarm after swarm of Scourge is finding a method to prevent living creatures from ever being turned into them. I have an idea for a fine powder that, when inhaled, may stop the entire process.\n\nI need withered tusks off the unliving Quilboar here to make this powder. Bring me an ample amount, and we may be able to stop the Scourge's growth for good.", sourceObjective = "Collect 20 Withered Tusks.", progress = "Do you have the tusks?", completion = "I have faith that this substance will prevent many future headaches. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27030] = { id = 27030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foxtails By The Handful", description = "We've seen more foxes in the hills lately. Cunning creatures, they are. A good test of a hunter's skills, and a fine profit to boot!\n\nIt's their tails, <lad/lass>. Fine and fluffy, they're just as good hung on yer belt to ward off fleas as they are to line the gloves of some fancy noble.\n\nListen to me prattle on. I'm no goblin; the thrill's in the hunt! But if you bring me back some foxtails, I'll still gladly pay you for 'em. You'll find the foxes just north of the lodge in the lower woodlands.", sourceObjective = "Collect 7 Fluffy Fox Tails.", progress = "What've you got for me?", completion = "Ahh, you see? Goods of the finest quality. Good work gettin' these.", sourceObjectiveStatus = "unverified-source-field" }
quests[27031] = { id = 27031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wing Nut", description = "I'm through with gyrocopters. Sure, they work, but when has that ever been good enough for a real gnome? I want real flight, with WINGS!\n\nI've been studying birds for years now, trying to unlock the final secret to building a machine that flies just like them. That elegant soaring and swooping, the rush of wind over the wings, ahh.\n\nYou! You can help me. I need the finest flight feathers you can find. The golden eagles circling near the lodge would be a fine choice...", sourceObjective = "Collect 3 Pristine Flight Feathers from Golden Eagles.", progress = "Only the finest feathers will do!", completion = "Beautiful. you've got an eye for quality!\n\nGreat minds think alike! It's clear you've got an enthusiasm for flight and fowl, so maybe you can help me further...", sourceObjectiveStatus = "unverified-source-field" }
quests[27032] = { id = 27032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bird is the Word", description = "I've actually nearly perfected my dream machine: The Skystrider! The world's first flying Mechanostrider! But, well�\n\nWhen I was putting the finishing touches on it in my secret cavern lab, my other creations became, er, jealous. Giving mechanical birds a personality to begin with was probably a bad idea, but that's already done.\n\nI need the Supermechanical Robo-Widget from the original Skystrider if I want to rebuild it! Please, journey into the cave and retrieve it for me!", sourceObjective = "Find the Rusted Skystrider inside Ironwing Cavern.", completion = "<The Skystrider sits silent, its chance to fly gone. An obvious hatch on the front is marked \"SRW\".>", sourceObjectiveStatus = "unverified-source-field" }
quests[27033] = { id = 27033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skystrider's Heart", description = "Opening the hatch, you find an imposing looking mechanical device hooked to several wires, gears, and who knows what else.\n\nIt's easily detached. Time to bring it back to Bingles.", sourceObjective = "Return the Supermechanical Robo-Widget to Bingles Blastenheimer at the Farstrider Lodge.", completion = "Perfect! Now that I've perfected the wing balance and have all the parts I need, all we need is a pilot.", sourceObjectiveStatus = "unverified-source-field" }
quests[27034] = { id = 27034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's That Age", description = "I'm not making the Skystrider for me, {name}. Not even for gnomekind. I want my son to be the one to fly it.\n\nI'm old, and my reflexes aren't what they used to be. But my boy Ando could be the best pilot Azeroth's ever seen, if he'd just get over his teenage moodiness!\n\nHe sits out by the loch, staring at the sky all day. Something's been bothering him, and yet he refuses to talk to his own father about it. I'm at a loss!\n\nPlease, {name}, could you go talk to him? Tell him I need him to pilot the Skystrider!", sourceObjective = "Speak to Ando Blastenheimer on the east side of the Loch.", completion = "I don't care about my father and his silly inventions! It's all just nonsense!", sourceObjectiveStatus = "unverified-source-field" }
quests[27035] = { id = 27035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standing Up", description = "Look at them. The Twilight's Hammer ruined this land!\n\nThat cult caused this Cataclysm, and broke the Stonewrought Dam, and drained the entire Loch. And now they wander around the ruins like it's their home!\n\nIf there was any justice in this world, someone would march into their camp and break that artifact of theirs in half. But I'm too weak to even try it.\n\nAnd nobody else is brave enough either! Not even you! You see? It's all so stupid...", sourceObjective = "Destroy the Twilight Landshaper at the center of the Twilight's Hammer Camp.", progress = "See what I mean? You don't even care either.", completion = "You did it? You did! You fought them and won!\n\nThere's hope after all...", sourceObjectiveStatus = "unverified-source-field" }
quests[27036] = { id = 27036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrin's Revenge", description = "I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say.\n\nA year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye.\n\nKill the bear, and I'm sure even Daryl would be speechless for once.\n\nThe bear, Ol' Sooty, can be found around his lair in the cave to the north.", sourceObjective = "Kill Ol' Sooty and obtain his head.", progress = "Ah, {name}! Back so soon? No doubt you've been at the hunt again? Don't worry if you've had some setbacks, in the long run it will make you better!\n\n...You couldn't get much worse, anyway...", completion = "Er... what's this? A bear's head, by the looks of it.\n\n<He runs a finger along his scar unconsciously.>\n\nWell, that's quite an interesting kill you have yourself there. Couldn't be that bear from back then...\n\n<He trails off then starts to visibly shake.>\n\nOh, take that away take it away! Get that grisly thing out of here!", sourceObjectiveStatus = "unverified-source-field" }
quests[27037] = { id = 27037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrin's Revenge", description = "Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!\n\nJust get it out of here, will you? No one wants to see your bloody little trophy, really!", sourceObjective = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.", progress = "Great job, {name}! We really showed him! Here, give me the head and I'll take care of it.", completion = "Thanks for helping me out with my little plan, {name}. I've been itching for months to get back at that snooty, stuck-up boy, and I'd say we did a pretty good job! Here, have this, you've earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27038] = { id = 27038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Parts", description = "<The Sergeant turns his attention to you.>\n\nLook here, if you want to help speed things up around here, get Flintlocke off my back. A whole shipment of siege engine parts was misplaced and now it's scattered all up and down the dock.\n\nGather up the missing parts and get them to Flintlocke so he can finish construction. He's just across the road from me, waiting.", sourceObjective = "Gather up 5 Missing Parts from around the Stormwind Harbor.", progress = "Eh wot?\n\nMy parts. Where are they? You can't build a tank without parts!\n\nIf yeh did, it'd be small. An' mostly inner-fectual.", completion = "<Flintlocke greedily digs through the machine parts, tossing choice picks over his shoulder.>\n\nOh aye, 'ere's the stuff.\n\n<He sticks his head all the way into one of the crates.>\n\nBut where's me powder? Everything's here but for the powder. I need explosives, man!\n\nYou tell the King, no powder, no power. I need me some kersplosions or I ain't leavin' port.", sourceObjectiveStatus = "unverified-source-field" }
quests[27039] = { id = 27039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Intentions", description = "Do you know why Mortuus appends 'nub' to your name, {name}? Because he is an incompetent sycophant that has trouble seeing through his oversized helmet. 'NUB' is your classification. You are now part of the NEW UNDERCITY BATALLION.\n\nBut enough with the comedy! I sent Deathstalker Yorick on a shadow operation two days ago. Her goal was to get information on the Gilneas Liberation Front and return. Three days and no word from her.\n\nHead southwest to the Ivar Patch and look for Yorick, {name}.", sourceObjective = "Find Deathstalker Yorick at the Ivar Patch in Silverpine Forest.", completion = "Belmont gets a little nervous and sends some newbie to look for me? Listen, I've been staking out the old Ivar cottage from inside this outhouse for three days. Your presence threatens the whole damn operation!\n\nThere's no time to explain. We have to act now or this mission will be compromised.", sourceObjectiveStatus = "unverified-source-field" }
quests[27040] = { id = 27040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decryption Made Easy", description = "We don't have the tools to decipher these encrypted plans. The Twilight's Hammer do, though.\n\nWould you be a sweetie and take the plans back up there to run them through their one-time decryption engines?", sourceObjective = "Decrypt 6 plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[27041] = { id = 27041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decryption Made Easy", description = "We don't have the tools to decipher these encrypted plans. The Twilight's Hammer do, though.\n\nWould you take the plans back up there and run them through their one-time decryption engines?", sourceObjective = "Decrypt 6 plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[27042] = { id = 27042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Fire and Water and Air with...", description = "Did ye hear the blatherin' idiot while ye were up there? That's none other than Haethen Kaul, their leader.\n\nThe man's gone daft with power. He's pullin' it straight from them bound elementals, makin' him nigh invincible.\n\nThe only thing I can think of to get ye into proper shape fer a fight with him is fer ye to first kill all o' them elementals, gettin' their wards. That should protect ye from Haethen's spells.\n\nWell, most o' them anyway.", sourceObjective = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul.", completion = "That's the ol' spirit! One less nasty in this world that the little ones will have ta worry about when they go ta sleep at night.\n\nNot ta mention that we won't have ta be worrying about him none no more neither!\n\nNow let's see here. I think we have somethin' in our crates that'll make a fittin' reward fer ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[27043] = { id = 27043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Fire and Water and Air with...", description = "Did you hear the man going on with his incessant yelling while you were up there? That's Haethen Kaul, their leader.\n\nIt's a well known fact that he's gone insane from the power he's drawing from their bound elementals. Unfortunately, it makes him nigh invincible.\n\nIf you're to fight him, you'll first have to kill each of the elementals, gaining their wards in the process. That should protect you from Haethen's magic.\n\nWell, most of it anyway.", sourceObjective = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul.", completion = "An excellent display of {class} prowess.\n\n\n\nI believe that a reward is in order. Something appropriate for a powerful man such as yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27044] = { id = 27044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peasant Problems", description = "I'm not quite ready to go back to the keep yet. Would you like to help me with something?\n\nRecently some of the local farmers were petitioning the King about some missing livestock. My father promised someone would investigate, but the city guard is stretched so thin it'll take weeks.\n\nI thought I would help! It'll encourage the farmers to see someone take action, especially from the royal family. Besides, it's just some missing cows. Nothing dangerous.\n\nTake me to Farmer Wollerton here in the city!", sourceObjective = "Escort Prince Anduin to Farmer Wollerton at the Wollerton Stead within Stormwind City. If he's no longer with you, you can find him in Stormwind Keep.", progress = "Uh, yup?", completion = "<On seeing the Prince Regent, Farmer Wollerton collapses awkwardly down on one knee.>\n\nY- Y- Your highness!", sourceObjectiveStatus = "unverified-source-field" }
